(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["audio"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-codec-int8-quant"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-int8-quant-sec-1\">一 · 从一次上线爆音说起：INT8 要解决的不是“省显存”而是“驻留路数”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-int8-quant-sec-2\">二 · 误差从哪来：两条量化路径与一个上界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-int8-quant-sec-3\">三 · 平滑变换：把量化难度从激活搬到权重</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-int8-quant-sec-4\">四 · 校准集偏差：事故的真正机制</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-int8-quant-sec-5\">五 · 适用边界的量化表述：什么时候该用，什么时候不该</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-int8-quant-sec-6\">六 · 一个可执行的启用判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-int8-quant-sec-7\">七 · 校准集偏差如何把 INT8 编解码器推成爆音源</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-int8-quant-sec-8\">八 · 校准阶段：动态范围统计的输入、输出与显存代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-int8-quant-sec-9\">九 · 激活平滑：把量化难度从激活迁移到权重</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-int8-quant-sec-10\">十 · 权重量化与激活量化：per-channel 与 per-tensor 的取舍</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-int8-quant-sec-11\">十一 · 推理热路径：INT8 矩阵乘与 epilogue 反量化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-int8-quant-sec-12\">十二 · 敏感层混合精度：输出投影与 RVQ 码本的高精度分支</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-int8-quant-sec-13\">十三 · 失败模式与逐层实测的工程判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-int8-quant-sec-14\">十四 · 量化流水线沿数据流的失效边界与系统代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-int8-quant-sec-15\">十五 · 量化误差上界的逐项拆解</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-int8-quant-sec-16\">十六 · 平滑变换的推导与通道因子选取</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-int8-quant-sec-17\">十七 · per-channel 与 per-tensor 的误差分配</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-int8-quant-sec-18\">十八 · 伪代码：从校准到 INT8 卷积</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-int8-quant-sec-19\">十九 · 敏感层混合精度的误差与调度代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-int8-quant-sec-20\">二十 · 校准集偏差下的饱和与工程判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-int8-quant-sec-21\">二十一 · 失效边界：平滑因子、校准偏差与 epilogue 反噬</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-int8-quant-sec-22\">二十二 · 请求形态：什么流量喂得饱 INT8 卷积</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-int8-quant-sec-23\">二十三 · 长度分布：长尾请求如何吃掉并发预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-int8-quant-sec-24\">二十四 · 并发与批大小：权重减半换来的路数怎么花</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-int8-quant-sec-25\">二十五 · 校准集：负载分布决定量化参数的有效域</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-int8-quant-sec-26\">二十六 · 负载不对时的三种崩法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-int8-quant-sec-27\">二十七 · 负载配方：什么样的请求形态才配得上 INT8 编解码器</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-int8-quant-sec-28\">二十八 · 硬件档位与并行拓扑的耦合约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-int8-quant-sec-29\">二十九 · 量化方案的层敏感度分档</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-int8-quant-sec-30\">三十 · KV 策略与激活显存的配比</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-int8-quant-sec-31\">三十一 · 调度参数：批、实时率与 SLO 的三角</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-int8-quant-sec-32\">三十二 · 可复现配置思路的落地顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-int8-quant-sec-33\">三十三 · 配方失效的三种边界：校准漂移、敏感层误伤与 epilogue 反噬</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-int8-quant-sec-34\">三十四 · 显存驻留与并发路数：权重减半不等于路数翻倍</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-int8-quant-sec-35\">三十五 · 带宽与算术强度：INT8 把瓶颈从算力推向访存</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-int8-quant-sec-36\">三十六 · 通信与多卡：权重量化改变的是切分账本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-int8-quant-sec-37\">三十七 · 功耗与热：吞吐翻倍不等于能效翻倍</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-int8-quant-sec-38\">三十八 · 尾延迟：混合精度分支与校准偏差是两大来源</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-int8-quant-sec-39\">三十九 · 规模上去先崩在哪里：按瓶颈排序的工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-int8-quant-sec-40\">四十 · 规模上去以后，先崩的是带宽与混合精度分支的调度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-int8-quant-sec-41\">四十一 · 校准集偏差引发的饱和削波与爆音</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-int8-quant-sec-42\">四十二 · 敏感层误量化：码本索引错位与音素级噪声</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-int8-quant-sec-43\">四十三 · 显存与批抖动：混合精度分支下的 OOM 与批形震荡</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-int8-quant-sec-44\">四十四 · 路由不均与尾延迟尖刺</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-int8-quant-sec-45\">四十五 · 监控指标与回滚判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-int8-quant-sec-46\">四十六 · 量化上线的暗礁：从校准漂移到混合精度分支的调度代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-int8-quant-sec-47\">四十七 · 同族算法的坐标：量化作用点与步数结构</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-int8-quant-sec-48\">四十八 · 决策表：四条路线的适用条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-int8-quant-sec-49\">四十九 · 判据的量化表达：收益与风险的边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-int8-quant-sec-50\">五十 · 具体例子：三条路线的分岔判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-int8-quant-sec-51\">五十一 · 与正交算法的叠加次序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-int8-quant-sec-52\">五十二 · 规模上限与工程落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-int8-quant-sec-53\">五十三 · 与相邻算法的边界对照：何时选 INT8 PTQ，何时不选</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:515px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 515.3 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"433.3\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">在校准集上统计各层权重与激活的动态范围</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"433.3\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">对激活做通道级平滑，把量化难度从激活迁移到权重</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"433.3\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">权重 per-channel INT8 量化，激活 per-tensor …</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"433.3\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">推理时卷积/线性层走 INT8 Tensor Core，反量化在 epil…</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"433.3\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">对量化敏感层（如输出投影、RVQ 码本）保留 FP16/BF16 混合精度</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-codec-int8-quant-sec-1\">一 · 从一次上线爆音说起：INT8 要解决的不是“省显存”而是“驻留路数”</h3>\n<p>某语音合成服务在 B200 上以 BF16 部署神经编解码器与声码器，单卡可稳定驻留若干路并发，白天负载下实时率与首包延迟都在 SLO 内。夜间灰度把权重与激活压到 INT8 后，峰值并发确实上去了，但监控里出现一类奇怪的告警：正常音量段落的输出干净，一旦遇到高能量、宽动态的音频片段——喊叫、近讲爆破音、带背景音乐的素材——解码器输出出现周期性爆音，声码器端表现为削波式失真，主观听感是“炸”。回滚后现象消失，复现实验指向同一根因：校准集只覆盖了单一说话人与单一语种，激活动态范围估计偏窄，上线后高能量输入把 INT8 表示推到饱和区，反量化回不到原来的幅度。</p>\n<p>这个事故定义了本算法的问题边界。它要解决的具体推理问题是：编解码器与声码器的卷积层、线性层权重与激活占用显存大、带宽压力高，在多路并发或边缘设备上直接限制可驻留路数与吞吐。权重显存减半不是目的，目的是同样的 HBM 里能多放几路会话、同样的带宽预算里能多喂几次前向。它不解决的问题同样清晰：RVQ 码本查找与输出投影的数值敏感度不会因为量化而消失，极低比特（如 INT4）在这些层上失真明显；它也不改变分块流式策略与自回归步数结构——量化只作用于单次前向的算力与显存，与流式编解码器分块推理、RVQ 分层码本渐进解码是正交的两件事。</p>\n\n<h3 id=\"alg-codec-int8-quant-sec-2\">二 · 误差从哪来：两条量化路径与一个上界</h3>\n<p>把权重与激活同时压到 INT8，误差由两个独立来源叠加：权重量化步长带来的扰动，与激活量化步长带来的扰动。对一层线性或卷积运算，输出误差的保守上界可写成</p>\n<div class=\"formula\">$$\\text{err} \\le \\frac{\\Delta_W \\|X\\| + \\Delta_X \\|W\\|}{2}$$</div>\n<p>其中 $\\Delta_W$、$\\Delta_X$ 分别是权重与激活的量化间隔。这个式子说明一件工程上很关键的事：误差不是单边可控的。只把权重压到 INT8、激活留在 BF16，$\\Delta_X$ 项消失，误差被 $\\Delta_W \\|X\\|$ 主导；而一旦激活也压到 INT8，$\\Delta_X \\|W\\|$ 这一项立刻进场，且 $\\|W\\|$ 在声码器上采样卷积里并不小。更麻烦的是 $\\Delta_X$ 由激活动态范围决定，而音频激活的动态范围随内容剧烈波动——静音段与爆破音段的幅度差可以跨若干数量级，per-tensor 单一缩放因子必然在某一端吃亏：缩放取宽了，静音段有效位被浪费；取窄了，高能量段饱和削波，正是事故里的爆音。</p>\n<p>权重量化侧相对温和，因为权重在训练后是静态的，per-channel 缩放可以把每个输出通道的步长压到该通道自身的动态范围上：</p>\n<div class=\"formula\">$$\\hat{W} = \\text{round}\\left(\\frac{W}{s_W}\\right)$$</div>\n<p>每个通道一个 $s_W$，离群通道不会拖累整层。激活侧则没有这么幸运，per-tensor 缩放是常态，per-channel 激活量化虽更精细，却在 epilogue 引入额外的反量化与缩放开销——这是后文要反复权衡的代价项。</p>\n\n<h3 id=\"alg-codec-int8-quant-sec-3\">三 · 平滑变换：把量化难度从激活搬到权重</h3>\n<p>既然激活难量化、权重好量化，工程上的做法是把难度迁移过去。对激活做通道级平滑，等价于在进入量化前对激活乘一个正的对角缩放、同时对权重除同一个缩放，数学上不改变层输出：</p>\n<div class=\"formula\">$$\\hat{x}=x\\cdot s,\\quad \\hat{W}=W/s$$</div>\n<p>平滑因子按通道取</p>\n<div class=\"formula\">$$s_j=\\max(|x_j|)^{\\alpha}/\\max(|W_j|)^{1-\\alpha}$$</div>\n<p>$\\alpha$ 在两端之间做插值：$\\alpha$ 偏大时更多难度压在权重上，激活的动态范围被压窄；$\\alpha$ 偏小时反过来。实践中 $\\alpha$ 按层扫，而不是全局一个值。这一步的直接收益是让 $\\hat{x}$ 与 $\\hat{W}$ 的动态范围更接近，per-channel 缩放再映射到 INT8 时两侧都不至于一边饱和一边浪费位宽。对编解码器而言，卷积层的通道维就是天然的 per-channel 轴，平滑因子按输入通道统计即可，不需要改网络结构。</p>\n<p>代价要算清楚：平滑是逐通道的乘除，在 Blackwell Tensor Core 上走 INT8 矩阵乘之前多了一次元素级缩放，属于访存与 ALU 混合的轻量开销；真正昂贵的是激活若采用 per-channel 量化，反量化必须落在 epilogue，每个输出元素都要乘回自己的缩放因子，这部分开销与输出通道数成正比。当卷积本身已经受带宽限制时，epilogue 的额外读写会让端到端吞吐不升反降——这是必须按层实测而非全局套用的判断。</p>\n\n<h3 id=\"alg-codec-int8-quant-sec-4\">四 · 校准集偏差：事故的真正机制</h3>\n<p>PTQ 不需要重训练，适合已训练好的编解码器快速部署，代价是全部数值决策都押在校准集上。校准阶段统计各层权重与激活的动态范围，激活的 $\\max(|x_j|)$ 直接决定平滑因子与量化步长。若校准集只覆盖单一说话人、单一语种、干净近讲录音，统计出的动态范围偏窄，上线后遇到高能量音频，INT8 饱和削波，输出爆音与失真——这不是量化算法本身错，而是校准分布与推理分布错配。</p>\n<p>工程上的补救有三层。第一层是校准集配方：必须覆盖目标说话人与音频内容分布，把高能量、宽动态、带噪、远场都纳入统计，边缘场景还需按内容自适应校准，因为边缘设备的输入分布比云端更不可控。第二层是敏感层保护：RVQ 码本查找与输出投影对量化极敏感，若被一并量化而未保留高精度分支，码本索引错位会产生音素级噪声，听感上比爆音更难排查；必须按层敏感度分析强制保留 FP16/BF16。第三层是运行时护栏：对激活幅度做监控，超阈值时切回高精度分支，代价是混合精度分支增加调度复杂度——同一层在不同请求间走不同精度的 kernel，批调度与显存规划都要为两条路径留余量。</p>\n<table class=\"mini\"><thead><tr><th>失败模式</th><th>触发条件</th><th>系统代价</th><th>处置</th></tr></thead><tbody><tr><td>饱和削波爆音</td><td>校准集动态范围偏窄，遇高能量音频</td><td>音质事故，需回滚，吞吐收益归零</td><td>扩校准集覆盖，按内容自适应校准</td></tr><tr><td>码本索引错位噪声</td><td>RVQ 码本查找与输出投影被量化</td><td>音素级噪声，难定位</td><td>敏感层强制保留 FP16/BF16</td></tr><tr><td>吞吐不升反降</td><td>per-channel 激活量化 epilogue 开销超过带宽收益</td><td>端到端吞吐下降</td><td>按层实测，只对收益为正的层启用</td></tr></tbody></table>\n\n<h3 id=\"alg-codec-int8-quant-sec-5\">五 · 适用边界的量化表述：什么时候该用，什么时候不该</h3>\n<p>收益侧可以定性拆成两项。权重显存减半直接抬高可驻留路数：编解码器与声码器的卷积权重在 BF16 下占据的显存，在多路并发时是硬约束，减半意味着同样 HBM 容量下并发路数上限抬升。算力侧 INT8 矩阵乘吞吐约为 BF16 的 2 倍，在 Blackwell Tensor Core 上这条路径是硬件原生支持的，不需要额外算子改造。两项叠加，吞吐与实时率的改善在多路并发场景最明显；边缘单路场景则主要吃显存与带宽红利，算力红利取决于该设备是否具备 INT8 张量单元。</p>\n<p>边界侧由三个比例决定。其一是混合精度分支比例：敏感层保留高精度的比例越高，显存与算力收益被侵蚀得越多，规模上限受此制约。其二是校准集覆盖度：覆盖越窄，上线后分布漂移导致失真的概率越高，这是规模上限的另一个约束。其三是 epilogue 开销占比：per-channel 激活量化在带宽受限的卷积上可能净亏，需按层实测。三者共同划出一条适用线——PTQ INT8 适合已训练编解码器的快速部署与多路并发扩容，不适合在 RVQ 码本与输出层上追求极低比特，也不适合校准数据无法代表线上分布的场合。</p>\n<p>与相邻算法的分工要一句话说清：量化作用于卷积层本身，不改变分块策略，因此与声码器分块流式上采样正交；量化只影响单次前向的吞吐与显存，不改变步数结构，因此与非自回归时长预测并行合成正交。判断是否启用，看的是“单次前向是否受权重显存与带宽约束”，而不是“是否流式”。</p>\n\n<h3 id=\"alg-codec-int8-quant-sec-6\">六 · 一个可执行的启用判据</h3>\n<p>把上述边界落成工程判据，按顺序问四个问题。第一，当前部署是否受权重显存或带宽约束——若是，INT8 的收益成立；若瓶颈在调度或通信，量化不解决问题。第二，敏感层清单是否已按层敏感度分析确定——RVQ 码本查找、输出投影必须默认保留 FP16/BF16，其余层才进入量化候选。第三，校准集是否覆盖目标说话人、语种与音频内容分布，边缘场景是否准备了按内容自适应校准的路径。第四，逐层实测 epilogue 开销：对每个候选层比较 INT8 路径与 BF16 路径的端到端时延，只保留净收益为正的层，而不是全局套用 per-channel 激活量化。</p>\n<p>事故复盘给出的最终判断是：那次灰度失败不是 INT8 不可用，而是校准集与敏感层保护同时缺位。修复路径是把校准集扩到多说话人、多语种、含高能量与带噪素材，并把 RVQ 码本与输出投影钉死在 BF16，其余卷积层走 INT8 加平滑。这样权重显存减半的收益保留，混合精度分支只覆盖少数层，调度复杂度可控，爆音与码本噪声两类失败模式被同时堵住。量化配置的正确形态是一张按层标注精度与缩放策略的表，而不是一个全局开关。</p>\n\n<h3 id=\"alg-codec-int8-quant-sec-7\">七 · 校准集偏差如何把 INT8 编解码器推成爆音源</h3>\n<p>线上事故的典型形态不是算错，而是\"算得太窄\"。某路多并发语音合成服务把编解码器与声码器的卷积层整体切到 INT8，校准集只取了单一说话人的安静语料，各层激活的动态范围被估得偏窄。上线后遇到高能量、宽动态的音频，激活在 <span class=\"inline-math\">round((X − z_X)/s_X)</span> 这一步直接饱和削波，解码端输出周期性爆音与失真，而离线评测的 PESQ 类指标完全看不出来——因为评测集和校准集同分布。这个案例说明：INT8 权重量化在编解码器上的失效点几乎不在权重侧，而在激活动态范围的估计上，误差上界 <span class=\"inline-math\">err ≤ (Δ_W‖X‖ + Δ_X‖W‖)/2</span> 里真正失控的是 Δ_X 项，权重 per-channel 缩放只能压住前半部分。</p>\n<p>由此划出它解决与不解决的边界。它解决的是权重与激活的显存占用和带宽压力：权重减半直接抬高多路并发时的可驻留路数，INT8 矩阵乘在 Blackwell Tensor Core 上吞吐约为 BF16 的两倍，对边缘推理芯片同样成立。它不解决的是 RVQ 码本查找与输出投影的数值敏感性——这两处一旦被一并量化，码本索引错位会表现为音素级噪声，必须按层敏感度分析强制保留 FP16/BF16 分支；它也不改变声码器分块流式上采样与非自回归时长预测的步数结构，量化只作用于单次前向的吞吐与显存。极低比特（INT4）在码本与输出层上失真明显，属于该方案的规模上限之外。</p>\n<p>系统代价要按层实测而非全局套用。per-channel 激活量化在 epilogue 引入额外反量化与缩放开销，若某层卷积本身已受带宽限制，端到端吞吐可能不升反降；混合精度分支则增加调度复杂度，批大小同时受 INT8 激活显存与 FP16/BF16 分支挤占。工程判断是：先用 <span class=\"inline-math\">s_j = max(|x_j|)^α / max(|W_j|)^(1−α)</span> 做通道级平滑把量化难度从激活迁到权重，再对输出投影、码本查找逐层做敏感度扫描决定精度档位，校准集必须覆盖目标说话人、语种与高能量音频，边缘场景还需按内容自适应校准——否则省下的显存会以爆音的形式还回来。</p>\n<table class=\"mini\"><thead><tr><th>层类型</th><th>量化策略</th><th>主要风险</th></tr></thead><tbody><tr><td>中间卷积/线性</td><td>权重 per-channel INT8，激活 INT8</td><td>校准集偏窄导致饱和削波</td></tr><tr><td>输出投影</td><td>保留 FP16/BF16</td><td>量化后音质劣化</td></tr><tr><td>RVQ 码本查找</td><td>保留高精度分支</td><td>索引错位、音素级噪声</td></tr></tbody></table>\n<h3 id=\"alg-codec-int8-quant-sec-8\">八 · 校准阶段：动态范围统计的输入、输出与显存代价</h3>\n<p>按请求流动顺序看，INT8 量化的第一步发生在离线校准，而不是在线推理。输入是校准集——一批覆盖目标说话人、语种、采样率与音频能量分布的音频片段，前向穿过编解码器与声码器；输出是每层权重张量的 per-channel 最大绝对值，以及每层激活张量的 per-tensor 或 per-channel 动态范围统计。这一步不产生任何推理延迟，但决定了后面所有 INT8 内核的数值上限。代价体现在校准集的覆盖度上：校准集偏窄，激活动态范围被低估，上线后遇到高能量音频直接饱和削波。工程上把校准当作一次“数据侧的前向扫描”，逐层记录 min/max 与直方图，供后续平滑因子求解使用。</p>\n<p>这一步的显存代价可以忽略，因为统计量只是每层几个标量或通道向量；真正的代价是校准前向本身要跑完整模型，卷积层激活在 BF16 下占用与一次普通推理相同。对声码器这类上采样结构，高层特征图的空间尺寸随上采样倍数放大，校准时的激活显存峰值往往出现在中间层而非输出层，因此统计必须逐层落盘而不能只留最终输出。校准集规模按层敏感度分配：RVQ 码本与输出投影附近层需要更多样本覆盖码本索引分布，卷积主干层则可适度稀疏。</p>\n<p>量化误差的上界在这里第一次被确定下来：</p>\n<div class=\"formula\">$$\\text{err} \\le \\frac{\\Delta_W \\|X\\| + \\Delta_X \\|W\\|}{2}$$</div>\n<p>其中 $\\Delta_W$、$\\Delta_X$ 分别是权重与激活的量化步长，由校准得到的动态范围决定。校准阶段把 $\\Delta_X$ 钉死，后续平滑步骤只能在这个上界内重新分配误差，不能突破它。一个具体例子：某层卷积权重 per-channel 动态范围为 $[-0.8, 0.8]$，激活 per-tensor 动态范围为 $[-40, 40]$，则权重步长细、激活步长粗，误差项 $\\Delta_X \\|W\\|/2$ 占主导——这正是下一步激活平滑要处理的对象。</p>\n\n<h3 id=\"alg-codec-int8-quant-sec-9\">九 · 激活平滑：把量化难度从激活迁移到权重</h3>\n<p>第二步对每层做通道级平滑变换，输入是校准得到的逐通道激活最大值 $\\max(|x_j|)$ 与逐通道权重最大值 $\\max(|W_j|)$，输出是平滑因子 $s_j$ 与变换后的权重。变换本身是恒等的代数重写：</p>\n<div class=\"formula\">$$\\hat{x}=x\\cdot s,\\quad \\hat{W}=W/s,\\quad s_j=\\max(|x_j|)^{\\alpha}/\\max(|W_j|)^{1-\\alpha}$$</div>\n<p>指数 $\\alpha$ 控制迁移强度，$\\alpha=0.5$ 是常用的对称折中。机制要点在于：激活的离群通道被缩小、权重的对应通道被放大，两者动态范围向彼此靠拢，per-channel INT8 缩放映射时两侧步长更均衡。这一步的输入输出都是离线张量，不进入推理热路径；推理时 $s_j$ 被折叠进前一层的 epilogue 缩放或本层的反量化系数，不额外增加一次逐元素乘。</p>\n<p>代价出现在数值侧而非性能侧：平滑把权重的动态范围撑大，若某通道权重被放大过头，per-channel INT8 的权重步长变粗，误差项 $\\Delta_W \\|X\\|/2$ 上升，与激活侧收益抵消。因此 $\\alpha$ 与逐层敏感度必须联合选择，不能全局套用同一值。工程判断是：对激活离群严重的卷积层（声码器上采样前的特征层常见）取偏大的 $\\alpha$，对权重本身已很均匀的层取偏小值甚至跳过平滑。平滑因子在部署时以每层一个通道向量存储，显存开销可忽略，但混合精度分支的层不做平滑，调度上要标记为“高精度路径”。</p>\n\n<h3 id=\"alg-codec-int8-quant-sec-10\">十 · 权重量化与激活量化：per-channel 与 per-tensor 的取舍</h3>\n<p>第三步把平滑后的权重与激活映射到 INT8。权重走 per-channel：每个输出通道一个缩放因子 $s_W$，$\\hat{W} = \\text{round}(W/s_W)$，输出是 INT8 权重张量加一组通道缩放向量。激活走 per-tensor 或 per-channel：$\\hat{X} = \\text{round}((X - z_X)/s_X)$，$z_X$ 为零点。选择 per-channel 激活能进一步压低误差，但反量化要在 epilogue 逐通道做缩放，开销随通道数线性增长；per-tensor 激活反量化是一次标量乘，epilogue 几乎免费。</p>\n<p>显存收益在这里兑现：权重从 BF16 的 2 字节压到 1 字节，卷积与线性层权重显存减半，直接转化为多路并发时可驻留的模型副本数或更大的批。带宽收益同样直接——权重读取量减半，对受带宽限制的卷积层，单次前向的权重流量下降，INT8 矩阵乘在 Blackwell Tensor Core 上的吞吐约为 BF16 的 2 倍。代价是精度：per-channel 权重在通道数少的层（如输出投影的窄通道）统计不稳定，通道内动态范围差异大时量化噪声明显；per-channel 激活的 epilogue 开销在卷积本身已受带宽限制时可能吃掉吞吐收益，需按层实测而非全局开启。</p>\n<table class=\"mini\"><thead><tr><th>对象</th><th>粒度</th><th>反量化位置</th><th>主要代价</th></tr></thead><tbody><tr><td>权重</td><td>per-channel</td><td>epilogue 通道缩放</td><td>窄通道统计不稳</td></tr><tr><td>激活</td><td>per-tensor</td><td>epilogue 标量乘</td><td>离群通道误差大</td></tr><tr><td>激活</td><td>per-channel</td><td>epilogue 逐通道缩放</td><td>epilogue 开销线性增长</td></tr></tbody></table>\n<p>具体例子：声码器某卷积层输出 512 通道，per-channel 激活量化在 epilogue 需 512 次缩放，若该层已接近带宽上限，这部分开销使端到端吞吐不升反降；同层改用 per-tensor 激活后 epilogue 退化为一次标量乘，吞吐恢复，代价是离群通道的量化误差上升，需靠平滑步骤提前压平。</p>\n\n<h3 id=\"alg-codec-int8-quant-sec-11\">十一 · 推理热路径：INT8 矩阵乘与 epilogue 反量化</h3>\n<p>在线推理时，请求进入编解码器编码器或声码器，逐层执行：输入激活已是 INT8（由上一层 epilogue 产出），权重为 INT8，卷积/线性层直接调用 Blackwell Tensor Core 的 INT8 矩阵乘指令，累加在 INT32 中进行，结果在 epilogue 乘以 $s_W \\cdot s_X$ 并加零点修正，输出重新量化为 INT8 供下一层使用。输入是 INT8 激活与 INT8 权重，输出是 INT8 激活加一次缩放，代价集中在 epilogue：每层一次缩放乘加，per-channel 时是向量化缩放。</p>\n<p>这条热路径的延迟构成是：INT8 矩阵乘本身吞吐翻倍，但 epilogue 与层间重量化引入固定开销，层数越多、通道越宽，开销占比越高。对编解码器这种深卷积栈，收益主要来自权重带宽减半；对声码器这种上采样结构，高层特征图空间尺寸大、通道相对窄，epilogue 的相对开销更显著。工程上把 epilogue 融合进矩阵乘的写回阶段，避免额外的中间张量往返显存——这一步在 Blackwell 上依赖内核实现，框架层（TensorRT-LLM、CUTLASS 派生内核）是否融合直接决定端到端是否真的提速。</p>\n<p>具体例子：一次声码器前向含数十个卷积层，若每层 epilogue 未融合、需把 INT32 累加结果写回再读，额外显存往返使带宽收益被抵消；融合后累加结果在寄存器内完成缩放与重量化，权重带宽减半的收益才落到实时率上。这里的判断标准是逐层实测：带宽受限层开 INT8 有净收益，计算受限层收益被 epilogue 稀释。</p>\n\n<h3 id=\"alg-codec-int8-quant-sec-12\">十二 · 敏感层混合精度：输出投影与 RVQ 码本的高精度分支</h3>\n<p>第四步之外还有一条并行路径：对量化敏感层保留 FP16/BF16。输入是层敏感度分析结果（按层量化后音质退化排序），输出是一张混合精度层表。典型敏感层是输出投影与 RVQ 码本查找——前者直接决定波形或特征的重建精度，后者是离散索引查表，量化误差会直接造成码本索引错位，表现为音素级噪声。这些层不走 INT8 内核，保持高精度权重与激活。</p>\n<p>代价是调度复杂度：一次前向里 INT8 层与 BF16 层交替，内核启动序列变长，层间数据类型切换需要显式重量化或保持两套激活缓冲。显存上，高精度分支的权重不享受减半收益，混合精度比例直接决定实际显存节省——若敏感层占比高，权重显存减半的收益被稀释，多路并发提升幅度收窄。因此敏感层表要在音质与并发之间做显式权衡，而不是把所有可疑层一律保留高精度。</p>\n<p>具体例子：RVQ 码本查找层若被一并量化，码本索引错位导致音素级噪声，且这种失真无法靠校准集扩大修复；强制保留 BF16 分支后音质恢复，代价是该层权重显存不降、内核切换增加一次数据类型转换。工程判断是按层敏感度分析给出最小高精度集合，把混合精度比例控制在可接受范围，并用端到端音质指标验证而非逐层指标。</p>\n\n<h3 id=\"alg-codec-int8-quant-sec-13\">十三 · 失败模式与逐层实测的工程判据</h3>\n<p>按数据流走完五步后，失败模式集中在三处。其一是校准集偏差：只覆盖单一说话人或单一语种，激活动态范围估计偏窄，上线遇到高能量音频时 INT8 饱和削波，输出爆音与失真——这类失败在校准阶段无法通过公式上界预警，只能靠校准集覆盖度与上线后的削波计数监控。其二是敏感层漏保留：RVQ 码本与输出投影被一并量化，码本索引错位产生音素级噪声，需按层敏感度强制保留高精度分支。其三是 epilogue 开销反噬：per-channel 激活量化在带宽受限卷积层上使吞吐不升反降，需逐层实测而非全局套用。</p>\n<p>工程判据可以写成一条逐层决策规则：对每层测三个量——权重带宽占比、epilogue 开销占比、量化后音质退化量；带宽占比高且退化小的层开 INT8 per-channel 权重加 per-tensor 激活；退化大的层进高精度分支；epilogue 开销吃掉收益的层退回 per-tensor 激活或保持 BF16。这条规则把“是否量化”从全局开关变成逐层配置，混合精度层表就是它的输出。规模上限由此确定：受混合精度分支比例与校准集覆盖度制约，边缘场景还需按内容自适应校准，极低比特（如 INT4）在 RVQ 码本与输出层上失真明显，不在本路径的适用范围内。</p>\n<p>最后落在具体机制上：推理热路径的收益兑现点不在矩阵乘指令本身，而在 epilogue 是否与写回融合、层间重量化是否避免显存往返；这两点决定权重带宽减半能否转化为实时率与并发路数的实际提升。</p>\n\n<h3 id=\"alg-codec-int8-quant-sec-14\">十四 · 量化流水线沿数据流的失效边界与系统代价</h3>\n<p>把量化步骤按请求—token—KV 的顺序铺开，每一步的代价并不均匀。校准阶段只发生一次：在校准集上逐层统计权重与激活的动态范围，输入是若干条覆盖目标说话人与音频内容的音频片段，输出是每层的 min/max 或分位数统计，代价是离线的一次前向扫描，不进入在线延迟。平滑阶段把激活的量化难度迁移到权重，<span class=\"formula\">$$\\hat{x}=x\\cdot s,\\quad \\hat{W}=W/s,\\quad s_j=\\max(|x_j|)^{\\alpha}/\\max(|W_j|)^{1-\\alpha}$$</span> 这一步的输入是逐通道统计量，输出是改写后的权重与等效缩放因子，代价是权重需要离线重排一次，且 $s_j$ 必须随层固化进推理图，否则在线重算会吃掉 epilogue 预算。真正的在线代价集中在卷积/线性层的 INT8 Tensor Core 乘加与 epilogue 反量化：权重显存减半直接抬高可驻留并发路数，但 per-channel 激活量化会在 epilogue 引入逐通道缩放，若该层本就受带宽约束，这部分开销可能抵消吞吐收益。</p>\n<p>失效条件按敏感度分层。RVQ 码本查找与输出投影对量化最敏感，一旦与主干一并压到 INT8，码本索引错位会产生音素级噪声，因此必须按层敏感度分析强制保留 FP16/BF16 分支——混合精度分支保住了音质，却让调度器在同一个前向内切换两种 Tensor Core 路径，增加图切分与 kernel 启动开销。更隐蔽的失效来自校准集偏差：只覆盖单一说话人或单一语种时，激活动态范围估计偏窄，上线遇到高能量音频即发生 INT8 饱和削波，输出爆音与失真。误差上界 <span class=\"formula\">$$\\text{err}\\le\\frac{\\Delta_W\\|X\\|+\\Delta_X\\|W\\|}{2}$$</span> 说明激活步长 $\\Delta_X$ 被低估时误差随 $\\|W\\|$ 线性放大，这正是窄校准集最危险的放大路径。</p>\n<p>工程判断落在“按层实测而非全局套用”。可先用一张小表把每层的收益与风险对齐：主干卷积层权重占比高、激活平稳，优先 INT8 并开 per-channel 权重缩放；输出投影与码本相关层标记为高精度；激活动态范围跨内容波动大的层，比较 per-tensor 与 per-channel 两种激活粒度的 epilogue 开销后再定。规模上限由混合精度分支比例与校准集覆盖度共同决定：高精度层越多，权重显存减半的收益越被稀释；校准集越窄，越需要按内容自适应校准，边缘场景尤其如此。极低比特（如 INT4）在码本与输出层失真明显，不应越过这条边界去换吞吐。</p>\n<table class=\"mini\"><thead><tr><th>步骤</th><th>输入</th><th>输出</th><th>主要代价</th></tr></thead><tbody><tr><td>校准统计</td><td>覆盖分布的音频片段</td><td>逐层动态范围</td><td>离线一次性，偏差即埋雷</td></tr><tr><td>通道平滑</td><td>逐通道 min/max</td><td>改写权重与 $s_j$</td><td>权重离线重排，$s_j$ 固化进图</td></tr><tr><td>INT8 前向</td><td>INT8 激活与权重</td><td>INT8 累加结果</td><td>epilogue 反量化，per-channel 更贵</td></tr><tr><td>混合精度分支</td><td>敏感层输入</td><td>FP16/BF16 输出</td><td>图切分与 kernel 切换开销</td></tr></tbody></table>\n<h3 id=\"alg-codec-int8-quant-sec-15\">十五 · 量化误差上界的逐项拆解</h3>\n<p>先把公式摆正：<span class=\"formula\">$$\\hat{W} = \\text{round}\\left(\\frac{W}{s_W}\\right),\\quad \\hat{X} = \\text{round}\\left(\\frac{X - z_X}{s_X}\\right),\\quad \\text{err} \\le \\frac{\\Delta_W \\|X\\| + \\Delta_X \\|W\\|}{2}$$</span>。这不是一句装饰，它是整个 INT8 编解码器量化方案的设计约束。逐项看：<span class=\"formula\">$$s_W$$</span> 是权重的缩放因子，<span class=\"formula\">$$\\Delta_W$$</span> 是权重量化步长，<span class=\"formula\">$$\\|X\\|$$</span> 是激活的范数（在卷积层里通常取该通道输出对应的输入块范数），<span class=\"formula\">$$\\Delta_X$$</span> 是激活步长，<span class=\"formula\">$$\\|W\\|$$</span> 是权重范数。误差上界由两项构成：第一项是权重被量化后，乘以真实激活所引入的偏差；第二项是激活被量化后，乘以真实权重所引入的偏差。两项相加再除以二，是因为 round 的截断误差在对称区间内最大为半步长。</p>\n<p>关键一步推导在于把权重误差与激活误差解耦。设真实输出 <span class=\"formula\">$$Y = WX$$</span>，量化输出 <span class=\"formula\">$$\\hat{Y} = \\hat{W}\\hat{X}$$</span>，则 <span class=\"formula\">$$Y - \\hat{Y} = (W - \\hat{W})X + \\hat{W}(X - \\hat{X})$$</span>。对第一项取范数上界，得到 <span class=\"formula\">$$\\|W - \\hat{W}\\| \\cdot \\|X\\| \\le \\frac{\\Delta_W}{2}\\|X\\|$$</span>；对第二项，注意 <span class=\"formula\">$$\\hat{W}$$</span> 的范数不超过 <span class=\"formula\">$$\\|W\\| + \\frac{\\Delta_W}{2}$$</span>，但在实际推导中通常把 <span class=\"formula\">$$\\hat{W}$$</span> 近似为 <span class=\"formula\">$$\\|W\\|$$</span> 量级，于是第二项上界为 <span class=\"formula\">$$\\frac{\\Delta_X}{2}\\|W\\|$$</span>。合并即得原式。这一步的意义在于：误差不是由单一层的动态范围决定，而是由权重步长与激活范数的乘积、激活步长与权重范数的乘积共同决定。当激活范数远大于权重范数时，第一项主导；反之第二项主导。这就是为什么单纯对权重做 per-channel 量化、而激活仍用 per-tensor 时，误差上界会被激活的离群通道撑大。</p>\n<p>落到系统代价上：这个上界直接对应显存与带宽的权衡。权重从 BF16 压到 INT8，权重显存减半，权重读取带宽减半；但若激活仍保留 BF16，激活带宽不变，卷积层的总带宽收益就被稀释。在 Blackwell Tensor Core 上，INT8 矩阵乘吞吐约为 BF16 的 2 倍，但前提是权重与激活都走 INT8。若混合精度分支比例过高，实际吞吐增益会低于 2 倍。具体例子：一个声码器上采样卷积层，权重形状为 <span class=\"formula\">$$C_{out} \\times C_{in} \\times K$$</span>，若 <span class=\"formula\">$$C_{in}$$</span> 通道中存在一个能量极高的通道，per-tensor 激活量化的 <span class=\"formula\">$$\\Delta_X$$</span> 会被该通道拉大，导致其余通道的有效比特数下降，误差上界第二项显著上升，输出出现可听的量化噪声。</p>\n\n<h3 id=\"alg-codec-int8-quant-sec-16\">十六 · 平滑变换的推导与通道因子选取</h3>\n<p>平滑变换写作 <span class=\"formula\">$$\\hat{x} = x \\cdot s,\\quad \\hat{W} = W / s$$</span>，其中 <span class=\"formula\">$$s$$</span> 是通道级平滑因子。推导的起点是：量化误差上界中，<span class=\"formula\">$$\\Delta_X \\|W\\|$$</span> 这一项对激活动态范围敏感。若把激活乘以 <span class=\"formula\">$$s$$</span>、权重除以 <span class=\"formula\">$$s$$</span>，数学上输出不变：<span class=\"formula\">$$(W/s)(x \\cdot s) = Wx$$</span>。但量化后的步长变了：激活的动态范围被缩放，权重的动态范围被反向缩放。目标是让两者的动态范围接近，从而在相同的 INT8 表示下，两者的有效量化精度都较高。</p>\n<p>通道因子的选取是推导的关键一步。给定第 <span class=\"formula\">$$j$$</span> 个输入通道，设激活最大绝对值为 <span class=\"formula\">$$\\max(|x_j|)$$</span>，权重最大绝对值为 <span class=\"formula\">$$\\max(|W_j|)$$</span>，取 <span class=\"formula\">$$s_j = \\max(|x_j|)^{\\alpha} / \\max(|W_j|)^{1-\\alpha}$$</span>。当 <span class=\"formula\">$$\\alpha = 0.5$$</span> 时，<span class=\"formula\">$$s_j$$</span> 是两者最大值的几何平均比，使得缩放后激活与权重的动态范围在几何意义上对齐。这个式子的推导来自一个平衡条件：希望 <span class=\"formula\">$$\\max(|x_j \\cdot s_j|)$$</span> 与 <span class=\"formula\">$$\\max(|W_j / s_j|)$$</span> 的比值接近 1。令两者相等，解出 <span class=\"formula\">$$s_j = \\sqrt{\\max(|x_j|)/\\max(|W_j|)}$$</span>，即 <span class=\"formula\">$$\\alpha = 0.5$$</span> 的特例。工程上 <span class=\"formula\">$$\\alpha$$</span> 可调，用来在激活与权重之间分配量化难度：<span class=\"formula\">$$\\alpha$$</span> 偏大时更多难度迁移到权重，权重 per-channel 量化能吸收；<span class=\"formula\">$$\\alpha$$</span> 偏小时更多难度留在激活，激活 per-tensor 量化容易饱和。</p>\n<p>系统代价方面，平滑因子是逐通道的，意味着推理时激活需要先乘 <span class=\"formula\">$$s_j$$</span> 再做量化，这一步在 epilogue 或预处理阶段完成，引入额外的逐通道乘法。对于卷积层，若 <span class=\"formula\">$$s_j$$</span> 在通道维上变化，反量化时需要在输出通道上做缩放，epilogue 开销与输出通道数成正比。具体例子：编解码器编码器的某个卷积层有 512 个输入通道，若对每个通道都做平滑，则每次前向需要 512 次额外的逐通道缩放；在批大小较大时，这部分开销可被矩阵乘掩盖，但在小批流式场景下，epilogue 的逐通道缩放可能成为延迟瓶颈。因此平滑因子的粒度需要与卷积实现匹配：若卷积在 Tensor Core 上以 <span class=\"formula\">$$C_{in}$$</span> 为内维做矩阵乘，则平滑因子可以折叠进权重的 per-channel 缩放中，避免运行时逐通道乘法。</p>\n\n<h3 id=\"alg-codec-int8-quant-sec-17\">十七 · per-channel 与 per-tensor 的误差分配</h3>\n<p>权重 per-channel INT8 量化意味着每个输出通道有独立的 <span class=\"formula\">$$s_W$$</span> 和 <span class=\"formula\">$$\\Delta_W$$</span>。代入误差上界，第一项变成 <span class=\"formula\">$$\\frac{\\Delta_{W,c}}{2}\\|X_c\\|$$</span>，其中 <span class=\"formula\">$$c$$</span> 是输出通道索引。由于每个通道独立选步长，<span class=\"formula\">$$\\Delta_{W,c}$$</span> 由该通道权重的最大绝对值决定，避免了全局最大权重拉大所有通道步长的问题。激活 per-tensor 量化则只有一个 <span class=\"formula\">$$\\Delta_X$$</span>，由整个激活张量的最大绝对值决定。误差上界的第二项 <span class=\"formula\">$$\\frac{\\Delta_X}{2}\\|W\\|$$</span> 因此被全局激活离群值主导。</p>\n<p>推导上的关键判断是：当激活存在离群通道时，per-tensor 激活量化的 <span class=\"formula\">$$\\Delta_X$$</span> 被拉大，第二项成为误差主项；此时即使权重 per-channel 量化做得再好，总误差仍由激活项决定。平滑变换的作用就是把激活的离群能量迁移到权重侧，让权重 per-channel 量化的细粒度去吸收。若不做平滑而直接对激活做 per-channel 量化，则 <span class=\"formula\">$$\\Delta_X$$</span> 变成逐通道的 <span class=\"formula\">$$\\Delta_{X,j}$$</span>，第二项变为 <span class=\"formula\">$$\\frac{\\Delta_{X,j}}{2}\\|W_j\\|$$</span>，误差被逐通道控制，但 epilogue 需要逐通道反量化，开销上升。</p>\n<p>系统代价的对比很直接：per-channel 激活量化在 epilogue 引入额外反量化与缩放开销，若卷积本身已受带宽限制，端到端吞吐不升反降。具体例子：一个受带宽限制的声码器卷积层，权重读取已是瓶颈，此时增加 per-channel 激活反量化只会增加计算而不减少带宽，吞吐不升反降。因此工程判断是：按层实测，对激活离群严重的层用平滑加 per-tensor，对激活分布均匀的层用 per-channel，而不是全局套用同一种粒度。</p>\n\n<h3 id=\"alg-codec-int8-quant-sec-18\">十八 · 伪代码：从校准到 INT8 卷积</h3>\n<p>把上述推导落到可实现层面，伪代码分三段：校准统计、平滑与量化参数求解、推理时 INT8 卷积与 epilogue 反量化。</p>\n<ul>\n<li>校准统计：对校准集逐层前向，记录每个卷积层输入激活的逐通道最大绝对值 <span class=\"formula\">$$\\max(|x_j|)$$</span> 与权重的逐输出通道最大绝对值 <span class=\"formula\">$$\\max(|W_c|)$$</span>。校准集需覆盖目标说话人与音频内容分布，否则激活动态范围估计偏窄。</li>\n<li>平滑与量化参数：对每个输入通道计算 <span class=\"formula\">$$s_j = \\max(|x_j|)^{\\alpha} / \\max(|W_j|)^{1-\\alpha}$$</span>，将权重按 <span class=\"formula\">$$W' = W / s$$</span> 变换，再对 <span class=\"formula\">$$W'$$</span> 做 per-channel INT8 量化得到 <span class=\"formula\">$$\\hat{W}$$</span> 与 <span class=\"formula\">$$s_W$$</span>；对平滑后的激活 <span class=\"formula\">$$x' = x \\cdot s$$</span> 做 per-tensor 量化得到 <span class=\"formula\">$$s_X$$</span> 与 <span class=\"formula\">$$z_X$$</span>。</li>\n<li>推理：卷积层以 INT8 权重与 INT8 激活走 Tensor Core 矩阵乘，累加在 INT32 中进行；epilogue 阶段做反量化 <span class=\"formula\">$$\\hat{Y} = (\\text{acc} - \\text{bias}) \\cdot s_W \\cdot s_X$$</span>，其中 bias 项按 <span class=\"formula\">$$z_X$$</span> 修正。敏感层（输出投影、RVQ 码本）跳过 INT8 路径，保留 FP16/BF16 分支。</li>\n</ul>\n<p>伪代码中的关键设计是 epilogue 的反量化顺序。若先乘 <span class=\"formula\">$$s_W$$</span> 再乘 <span class=\"formula\">$$s_X$$</span>，两次缩放可以合并为一个因子，减少 epilogue 指令数。但若激活是 per-channel 量化，则 <span class=\"formula\">$$s_X$$</span> 是向量，反量化变成逐通道乘法，无法合并为标量。这就是 per-channel 激活量化增加 epilogue 开销的来源。系统代价上，INT8 矩阵乘的吞吐约为 BF16 的 2 倍，但 epilogue 的反量化与缩放是标量或向量操作，若 epilogue 成为瓶颈，实际吞吐增益会被压缩。具体例子：一个批大小为 8 的编解码器推理，INT8 矩阵乘部分耗时占比高，epilogue 占比低，吞吐增益接近 2 倍；若批大小降到 1 的流式场景，矩阵乘规模变小，epilogue 占比上升，吞吐增益下降。</p>\n\n<h3 id=\"alg-codec-int8-quant-sec-19\">十九 · 敏感层混合精度的误差与调度代价</h3>\n<p>RVQ 码本查找与输出投影对量化敏感，原因是这些层的输出直接决定码本索引或最终波形，量化误差不会被后续层平均掉。从误差上界看，输出投影层的 <span class=\"formula\">$$\\|W\\|$$</span> 与 <span class=\"formula\">$$\\|X\\|$$</span> 都较大，且输出维度通常等于码本大小或波形采样数，误差直接映射到索引错位或音素级噪声。因此这些层保留 FP16/BF16，不进入 INT8 路径。</p>\n<p>混合精度分支的调度代价体现在两方面：一是显存，敏感层保留 BF16 权重，权重显存减半的收益被部分抵消，可驻留路数取决于混合精度分支的比例；二是调度，INT8 层与 BF16 层交替执行，需要在层间切换 Tensor Core 的数据类型，切换本身有开销，且批内不同请求若走不同分支，批调度复杂度上升。具体例子：若 RVQ 码本查找层保留 BF16，则该层权重显存不缩减，而码本本身通常是查找表而非矩阵乘，量化收益本就有限；此时把码本查找与输出投影一并量化而未保留高精度分支，会导致码本索引错位，输出出现音素级噪声。工程判断是按层敏感度分析强制保留 FP16/BF16，而不是按全局比例一刀切。</p>\n<p>误差上界在这里给出一个定量直觉：敏感层的 <span class=\"formula\">$$\\Delta_W \\|X\\|$$</span> 项若不能被后续层稀释，就必须靠降低 <span class=\"formula\">$$\\Delta_W$$</span> 来控制，而降低 <span class=\"formula\">$$\\Delta_W$$</span> 的最直接方式就是保留更高精度。这就是混合精度分支存在的数学理由，不是工程上的保守选择。</p>\n\n<h3 id=\"alg-codec-int8-quant-sec-20\">二十 · 校准集偏差下的饱和与工程判据</h3>\n<p>激活动态范围随音频内容波动大，校准集偏差会导致爆音或失真。从公式看，若校准集只覆盖单一说话人或单一语种，<span class=\"formula\">$$\\max(|x_j|)$$</span> 估计偏窄，<span class=\"formula\">$$s_X$$</span> 偏小，上线后遇到高能量音频时 INT8 饱和削波，<span class=\"formula\">$$\\Delta_X$$</span> 的实际有效值被截断，误差上界第二项失效，输出出现爆音。这是校准集覆盖度直接决定量化上界有效性的例子。</p>\n<p>工程判据有三条：第一，校准集必须覆盖目标说话人、语种与音频内容分布，且包含高能量片段，使 <span class=\"formula\">$$\\max(|x_j|)$$</span> 不被低估；第二，对激活做平滑时 <span class=\"formula\">$$\\alpha$$</span> 的选择要按层实测，不能全局固定，因为不同层的激活离群程度不同；第三，per-channel 激活量化是否启用，要按层实测端到端吞吐，若卷积已受带宽限制则不应启用。规模上限受混合精度分支比例与校准集覆盖度制约，边缘场景需按内容自适应校准，而不是用一套固定参数覆盖所有内容。</p>\n<p>最后落在具体机制上：INT8 量化的收益不是无条件的，它由误差上界的两项共同约束。权重 per-channel 量化压低第一项，平滑变换把激活离群能量迁移到权重侧以压低第二项，敏感层保留高精度以规避不可稀释的误差，校准集覆盖度高能量内容以保证 <span class=\"formula\">$$\\Delta_X$$</span> 不被低估。这四件事共同决定 INT8 编解码器推理能否在 Blackwell Tensor Core 上真正拿到接近 2 倍的吞吐增益与权重显存减半的驻留收益。</p>\n\n<h3 id=\"alg-codec-int8-quant-sec-21\">二十一 · 失效边界：平滑因子、校准偏差与 epilogue 反噬</h3>\n<p>平滑变换 $$\\hat{x}=x\\cdot s,\\quad \\hat{W}=W/s$$ 的推导关键一步在于把量化误差写成两项之和：$\\text{err}\\le\\frac{\\Delta_W\\|X\\|+\\Delta_X\\|W\\|}{2}$。当 $s_j=\\max(|x_j|)^{\\alpha}/\\max(|W_j|)^{1-\\alpha}$ 取 $\\alpha=0.5$ 时，两项乘积 $\\Delta_W\\|X\\|$ 与 $\\Delta_X\\|W\\|$ 趋于相等，即误差在权重侧与激活侧被均摊——这是 SmoothQuant 式迁移的数学本质，也是它唯一的成立条件。一旦某通道的 $\\max(|x_j|)$ 在校准集上被低估（单一说话人、窄动态范围素材），$s_j$ 偏小，激活被压进 INT8 后直接撞上饱和区，削波不可逆；反过来若 $\\max(|W_j|)$ 极小，$s_j$ 被放大，权重 per-channel 缩放后的量化步长 $\\Delta_W$ 反而变粗。工程判断是：平滑因子必须按通道打印出 $\\max(|x_j|)/\\max(|W_j|)$ 的分布直方图，对长尾通道单独回退到 BF16，而不是全局套用同一 $\\alpha$。</p>\n<p>第二个边界在 epilogue。per-channel 激活量化意味着反量化缩放因子随通道变化，卷积在 Tensor Core 上算完后，epilogue 需按输出通道逐一乘回 $s_X s_W$ 并做 INT32→INT8 的饱和截断。若该层本就处于带宽受限区间（权重已减半、算术强度低），epilogue 的额外读取与缩放指令会把端到端延迟吃掉，出现“量化后吞吐不升反降”。判定方法是按层实测：只有当该层 INT8 矩阵乘的理论加速比大于 epilogue 开销占比时，才保留 INT8；对声码器上采样前的窄通道卷积，往往直接留在 BF16 更划算。</p>\n<p>敏感层清单必须硬编码进部署配方，不能交给统一量化器自动决定。RVQ 码本查找是索引操作而非矩阵乘，量化它只会让码本索引错位、产生音素级噪声；输出投影的动态范围随音频能量剧烈波动，是削波的第一现场。这两类层保留 FP16/BF16 后，混合精度分支带来的调度代价体现在批内分裂：同一 batch 中 INT8 层与 BF16 层交替，Tensor Core 需在两种 MMA 形态间切换，kernel launch 与流水线气泡增加。规模上限因此不由比特数决定，而由混合精度分支占全模型 FLOPs 的比例与校准集覆盖度共同约束——边缘多路并发场景应按目标语种与说话人分层校准，而非用一份通用校准集打天下。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>观测信号</th><th>处置</th></tr></thead><tbody><tr><td>校准集动态范围偏窄</td><td>高能量段输出爆音、削波</td><td>按内容分层校准，长尾通道回退 BF16</td></tr><tr><td>码本/输出层被量化</td><td>音素级噪声、索引错位</td><td>按层敏感度强制保留高精度分支</td></tr><tr><td>epilogue 开销超过收益</td><td>端到端吞吐不升反降</td><td>按层实测，窄通道卷积留 BF16</td></tr></tbody></table>\n<h3 id=\"alg-codec-int8-quant-sec-22\">二十二 · 请求形态：什么流量喂得饱 INT8 卷积</h3>\n<p>INT8 权重量化在编解码器上的收益不是均匀分布的，它挑请求形态。收益最扎实的形态是<strong>批量、离线或准实时的整段合成</strong>：一次请求携带完整音频片段，编解码器与声码器的卷积层在单次前向中处理长序列，权重在 L2 与寄存器之间被反复复用，INT8 的 2 倍矩阵乘吞吐能真正兑现成端到端加速。相反，<strong>细粒度流式请求</strong>——每几十毫秒推一个分块、每块只含少量帧——单次前向的算术强度被压得很低，卷积层更多时间花在等待激活与权重搬运上，此时 INT8 的算力优势被访存瓶颈吞掉。判断一个部署是否属于前一类，看两个量：单次前向的帧数与批内并发路数。帧数越长、路数越多，权重复用次数越高，量化收益越接近理论上限；帧数短、路数少，收益趋近于零甚至为负。</p>\n<p>请求形态还决定混合精度分支的调用频率。输出投影与 RVQ 码本查找必须保留 FP16/BF16，这两处是逐请求、逐帧都要走的路径。整段合成时它们占总计算的比例小，因为主体卷积足够长；流式小块时它们占比急剧上升，混合精度分支的调度开销与 kernel launch 次数成为主导项。工程上因此有一个明确的配方判断：<strong>把 INT8 主卷积留给长序列批处理路径，把短块流式路径交给 BF16 或保留 INT8 但不指望吞吐提升</strong>。这不是精度问题，是算术强度问题。</p>\n<div class=\"formula\">$$\\text{算术强度} = \\frac{2 \\cdot F \\cdot B \\cdot C_{in} \\cdot C_{out}}{(F \\cdot B \\cdot C_{in} + C_{in} \\cdot C_{out})\\cdot \\text{bytes}}$$</div>\n<p>式中 F 为帧数、B 为批内路数。F·B 增大时分母中的激活项相对权重项增长更快，权重复用率上升，INT8 的 2 倍吞吐才有落点。一个具体例子：同一台 Blackwell 节点上，整段 10 秒音频、批 8 路的合成请求，卷积层算术强度足以让 INT8 路径跑满 Tensor Core；而 40 ms 分块、批 1 路的流式请求，同一层的时间几乎全耗在激活读写上，INT8 与 BF16 的端到端延迟差落在噪声范围内。</p>\n\n<h3 id=\"alg-codec-int8-quant-sec-23\">二十三 · 长度分布：长尾请求如何吃掉并发预算</h3>\n<p>长度分布对 INT8 的影响比对 BF16 更尖锐，因为量化把权重显存减半之后，<strong>激活显存成为新的并发上限</strong>。编解码器与声码器的激活随帧数线性增长，且混合精度分支的激活不能压到 INT8。设权重显存为 M_w、单路激活为 a·L（L 为帧长），则可驻留路数近似为：</p>\n<div class=\"formula\">$$N_{\\max} \\approx \\left\\lfloor \\frac{M_{\\text{free}} - M_{\\text{fp16-branch}}}{M_w^{\\text{int8}} + a \\cdot L} \\right\\rfloor$$</div>\n<p>权重减半让分母第一项变小，但第二项随 L 增长。若线上长度分布是重尾的——大量短请求夹杂少量长音频——按平均长度做容量规划会低估长请求的激活占用，长请求到达时挤占并发槽位，短请求被迫排队，尾延迟抬升。工程做法是按分位数而非均值定批大小：以 P95 或 P99 帧长作为激活预算基准，短请求走小批快路径，长请求单独进大批路径并限制其并发数。这本质上是把长度分布切成两段负载配方，而不是一套参数打天下。</p>\n<p>代价落在显存与调度两侧。显存侧，per-channel 激活量化虽能压缩激活位宽，但 epilogue 的反量化与缩放需要额外暂存，抵消一部分节省；调度侧，长短请求混批会让批内张量按最长序列补齐，短请求的有效算力被浪费。一个具体例子：某路并发中 90% 请求为 2 秒、10% 为 30 秒，若统一按 30 秒分配激活预算，可驻留路数被长尾拖低数倍；改为两档批大小后，短请求档的驻留路数回升，长请求档以较低并发换取不排队，整体吞吐与尾延迟同时改善。</p>\n\n<h3 id=\"alg-codec-int8-quant-sec-24\">二十四 · 并发与批大小：权重减半换来的路数怎么花</h3>\n<p>权重显存减半的直接红利是可驻留路数上升，但这份红利是否兑现取决于批大小是否落在 INT8 卷积的高效区间。Blackwell Tensor Core 的 INT8 矩阵乘在批维度上有最小有效 tile，批太小则 tile 利用率不足，吞吐按批线性增长的那段曲线还没走完；批太大则激活显存与 epilogue 开销反噬。存在一个<strong>批大小甜点区</strong>：批内路数足以填满 MMA tile、激活占用仍在预算内、混合精度分支的调度开销被摊薄。配方上应把甜点区测出来而不是猜——按层实测端到端吞吐随批大小的曲线，取拐点。</p>\n<p>并发路数与批大小不是一回事。连续批处理下，批是动态拼装的，路数是稳态驻留量。INT8 让权重常驻显存变小，稳态路数上限提高，但每路的激活与 KV 类中间态并未同比例缩小。因此并发提升的瓶颈会从权重侧迁移到激活侧与调度侧：调度器拼批的频率、混合精度分支的切换次数、epilogue 反量化的额外指令都随路数增长。一个具体例子：单卡权重从 BF16 切到 INT8 后权重占用减半，理论上路数翻倍，但实测路数提升受限于激活预算与 epilogue 开销，实际提升幅度小于 2 倍；把批大小从 1 提到 4 到 8 的区间内，吞吐随批近似线性上升，超过该区间后 epilogue 与激活带宽成为瓶颈，曲线走平。</p>\n<p>这里有一个必须按层判断的陷阱：per-channel 激活量化在 epilogue 引入反量化与缩放开销，若该卷积层本身已受带宽限制（低算术强度、小通道数），这份开销会让端到端吞吐不升反降。配方上对这类层保留 per-tensor 激活量化或直接走 BF16，只对高算术强度的主体卷积套 per-channel。全局套用同一套量化配置是最常见的负载错配。</p>\n\n<h3 id=\"alg-codec-int8-quant-sec-25\">二十五 · 校准集：负载分布决定量化参数的有效域</h3>\n<p>校准集不是随便采一批音频，它必须覆盖<strong>目标负载的说话人、语种、内容类型与能量分布</strong>。INT8 量化的缩放因子由校准统计出的动态范围决定，动态范围估窄了，上线遇到高能量音频时激活饱和削波，输出爆音与失真。这是负载配方里最隐蔽的失败模式：离线指标正常，线上特定流量触发削波。校准集的覆盖度直接决定量化参数的有效域，有效域之外的请求就是精度事故。</p>\n<p>配方上把校准集与线上流量分布对齐：按说话人、语种、音频类型分层采样，能量分布覆盖从安静到高动态的区间，并对高能量段单独加权，避免均值统计被大量安静样本拉低动态范围。边缘场景还需按内容自适应校准——同一模型在不同内容域上的动态范围差异大，固定一套缩放因子会在跨域时失准。代价是校准成本与维护成本：校准集需要随流量分布漂移而更新，否则量化参数逐渐偏离有效域。</p>\n<p>一个具体例子：校准集只覆盖单一说话人、单一语种，激活动态范围估计偏窄；上线后遇到高能量音乐类音频，INT8 激活饱和，声码器输出出现周期性爆音。修复不是调高全局缩放，而是扩充校准集覆盖该内容域并重估 per-channel 缩放。另一类失败是 RVQ 码本查找与输出投影被一并量化而未保留高精度分支，码本索引错位导致音素级噪声——这属于敏感层识别缺失，需按层敏感度分析强制保留 FP16/BF16，而不是靠负载配方补救。</p>\n\n<h3 id=\"alg-codec-int8-quant-sec-26\">二十六 · 负载不对时的三种崩法</h3>\n<p>负载与配方错配时，症状有明确的三类。第一类是<strong>算力空转</strong>：流式短块、批 1 路的请求形态下，INT8 卷积的算术强度不足，权重搬运主导时延，量化带来的 2 倍算力无处施展，端到端延迟与 BF16 持平甚至因 epilogue 开销略差。第二类是<strong>显存错算</strong>：按平均长度规划并发，长尾长请求到达时激活超预算，触发排队或 OOM，尾延迟陡升；权重减半的红利被激活侧吃掉。第三类是<strong>精度越界</strong>：校准集覆盖不足，线上流量落在量化参数有效域之外，出现削波爆音或码本索引错位噪声，且离线评测无法复现。</p>\n<p>三类崩法的共同点是：它们都不是量化算法本身的问题，而是负载配方与量化配置的匹配问题。工程判断上，部署前必须做三件事——按目标请求形态测算术强度、按长度分位数定激活预算、按流量分布分层校准。任何一项缺失，INT8 的收益都会被某一类崩法抵消。规模上限也由此决定：受混合精度分支比例与校准集覆盖度制约，混合精度分支占比越高、校准覆盖越窄，可安全套用 INT8 的负载范围越小；极低比特（如 INT4）在 RVQ 码本与输出层上失真明显，不在本配方的适用域内。</p>\n<p>配方落地的具体机制是分档：按请求形态与长度把流量切成若干档，每档绑定独立的批大小、激活预算与量化配置（主体卷积 INT8 per-channel、敏感层 BF16、低算术强度层 per-tensor 或 BF16），档间由调度器按请求特征路由。这套分档机制把负载配方从“一套全局参数”变成“按流量特征匹配的配置集合”，是 INT8 编解码器在多路并发服务中稳定兑现吞吐与音质的前提。</p>\n\n\n<h3 id=\"alg-codec-int8-quant-sec-27\">二十七 · 负载配方：什么样的请求形态才配得上 INT8 编解码器</h3>\n<p>这套 PTQ 方案的收益不是无条件成立的，它把权重与激活压到 INT8，收益兑现的前提是<b>请求形态与批结构能填满 INT8 Tensor Core 的矩阵乘维度，同时混合精度分支的比例足够低</b>。设单层量化误差按 <span class=\"formula\">$$\\text{err} \\le \\frac{\\Delta_W \\|X\\| + \\Delta_X \\|W\\|}{2}$$</span> 上界估计，其中 $\\Delta_W,\\Delta_X$ 分别是权重与激活的量化步长；平滑因子 $s_j=\\max(|x_j|)^{\\alpha}/\\max(|W_j|)^{1-\\alpha}$ 的作用是把 $\\Delta_X\\|W\\|$ 这一项压下去，代价是把难度搬到权重侧，由 per-channel 缩放吸收。于是负载配方的第一条判据是：<b>校准集必须覆盖上线流量的能量分布</b>，否则 $\\max(|x_j|)$ 被低估，$\\Delta_X$ 偏小，高能量音频直接饱和削波。</p>\n<p>适合的请求形态是<b>中等长度、批内长度方差可控的编解码/声码器前向</b>：短请求（几十毫秒级音频帧）单次前向的矩阵乘规模小，INT8 的吞吐优势被 epilogue 反量化与 kernel launch 开销吃掉；长请求则让激活显存随批大小线性上涨，而混合精度分支（输出投影、RVQ 码本查找）不参与 INT8 压缩，成为显存与调度的硬约束。多路并发时权重显存减半直接抬高可驻留路数，这是本方案最确定的收益；但若并发路数被混合精度分支的激活峰值卡住，权重省下来的显存就换不成吞吐。批大小应按“INT8 层激活显存 + 高精度分支峰值”取折中，而不是按权重显存反推。</p>\n<p>负载不对时的失效是分层的。校准集只覆盖单一说话人或单一语种，动态范围估计偏窄，上线遇到高能量内容即出现爆音与失真；RVQ 码本查找与输出投影被一并量化而未保留 FP16/BF16 分支，码本索引错位表现为音素级噪声，必须按层敏感度分析强制保留高精度。更隐蔽的一种是 per-channel 激活量化：它在 epilogue 引入额外反量化与缩放开销，若该卷积层本身已受带宽限制，端到端吞吐不升反降——这类层要按层实测，不能全局套用同一配方。</p>\n<table class=\"mini\"><thead><tr><th>负载特征</th><th>适配判断</th><th>主要代价</th></tr></thead><tbody><tr><td>批内长度方差小、中等帧长</td><td>适配，INT8 吞吐可兑现</td><td>epilogue 反量化开销</td></tr><tr><td>极短帧、批大小=1</td><td>不适配，收益被 launch 开销吞没</td><td>延迟不降</td></tr><tr><td>高能量/多说话人混合流量</td><td>需内容自适应校准，否则削波</td><td>音质失效</td></tr><tr><td>混合精度分支占比高</td><td>收益受显存峰值制约</td><td>调度复杂度上升</td></tr></tbody></table>\n<h3 id=\"alg-codec-int8-quant-sec-28\">二十八 · 硬件档位与并行拓扑的耦合约束</h3>\n<p>部署配方的第一层决策不是选量化方案，而是先确定硬件档位，因为 INT8 路径的收益形态在不同档位上完全不同。Blackwell Tensor Core GPU（B200/B300、GB200/GB300 NVL72）上，INT8 矩阵乘吞吐约为 BF16 的 2 倍，这一倍数只有在卷积/线性层真正落到 INT8 MMA 指令、且 epilogue 反量化不成为瓶颈时才兑现；边缘推理芯片上 INT8 往往是唯一可用的高吞吐路径，但缺少与 Blackwell 等价的 epilogue 融合能力，per-channel 激活量化的缩放开销会被放大。因此配方必须把“权重 per-channel INT8 + 激活 per-tensor 或 per-channel INT8”写成档位相关的开关，而不是全局常量。</p>\n<p>并行拓扑上，编解码器与声码器的卷积层是带宽敏感型负载，张量并行（TP）切分权重会引入每层的 all-reduce，在 NVLink 5 域内可接受，但跨节点走 NCCL 时通信量会吃掉 INT8 带来的显存收益。工程判断是：单卡能驻留的并发路数由 INT8 权重显存减半直接抬高，优先做单卡多路而不是 TP 扩展；只有当单卡显存仍不足、且 SLO 允许增加单次前向延迟时，才启用 TP=2 并把敏感层的高精度分支固定在单卡上以避免跨卡混合精度同步。流水并行对编解码器意义有限，因为层数不足以摊薄气泡。</p>\n<p>一个具体例子：GB200 NVL72 单节点内以 4 卡承载编解码器前端、声码器后端分离部署，前端走 INT8 卷积、后端声码器上采样保留 BF16，两段之间用 NIXL 传 latent，避免把混合精度分支跨进程拆散。代价是分离部署增加一次显存到显存的搬运延迟，收益是每段可以独立按档位选量化方案。</p>\n\n<h3 id=\"alg-codec-int8-quant-sec-29\">二十九 · 量化方案的层敏感度分档</h3>\n<p>配方不能写成“全模型 INT8”，而要按层敏感度分三档。第一档是全 INT8：编解码器主干卷积、声码器前段上采样卷积，权重 per-channel、激活 per-tensor，反量化在 epilogue 完成。第二档是平滑后 INT8：激活动态范围随音频内容波动大的层，先做通道级平滑 <span class=\"formula\">$$\\hat{x}=x\\cdot s,\\quad \\hat{W}=W/s$$</span>，平滑因子取 <span class=\"formula\">$$s_j=\\max(|x_j|)^{\\alpha}/\\max(|W_j|)^{1-\\alpha}$$</span>，把量化难度从激活迁移到权重，再对权重做 per-channel INT8。第三档是强制高精度：输出投影、RVQ 码本查找、声码器末段波形重建层保留 FP16/BF16。</p>\n<p>分档依据是量化误差上界 <span class=\"formula\">$$\\text{err} \\le \\frac{\\Delta_W \\|X\\| + \\Delta_X \\|W\\|}{2}$$</span>，其中 Δ_W、Δ_X 分别是权重与激活的量化步长。平滑降低 Δ_X 的同时抬高 Δ_W，两者乘积项决定误差是否可控；对输出投影这类 ‖X‖ 与 ‖W‖ 都大的层，单靠平滑压不住误差，必须走第三档。RVQ 码本查找不是矩阵乘而是查表，INT8 化会直接造成码本索引错位，产生音素级噪声，因此这一层的高精度分支是硬约束而非调优项。</p>\n<p>系统代价上，第三档比例直接决定收益上限：混合精度分支越多，权重显存减半的实际幅度越小，调度复杂度越高——每个 batch 内要同时管理 INT8 与 BF16 两组权重指针与不同的 epilogue 路径。工程上把第三档层数控制在个位数百分比，是保住“权重显存减半、多路并发提升”这一核心收益的经验边界；超出则需重新评估是否值得上 INT8。</p>\n\n<h3 id=\"alg-codec-int8-quant-sec-30\">三十 · KV 策略与激活显存的配比</h3>\n<p>编解码器推理的 KV 形态与自回归 LM 不同：声码器与卷积编解码器主干基本无 KV，真正的缓存压力来自自回归码本 LM 分支的码本历史与 RVQ 分层状态。配方里 KV 策略要按分支拆开写：卷积主干不分配 KV，只按批大小预留 INT8 激活工作区；码本 LM 分支按路数分配 KV，且 KV 本身不做 INT8（KV 量化属于另一条线，此处只做指路），保持 BF16 以避免与码本索引精度叠加失真。</p>\n<p>激活显存的估算决定批大小上限。INT8 激活把每层工作区压到 BF16 的一半，但 per-channel 激活量化会在 epilogue 引入额外的缩放张量，其显存与通道数成正比，在宽通道卷积上不可忽略。配方写法是：先按 INT8 激活估算单路工作区，再乘以目标并发路数，加上第三档高精度分支的 BF16 工作区，得到单卡显存占用；若超出，优先降批而不是降精度档位，因为降档位会直接损伤音质而降压批只损失吞吐。</p>\n<p>具体例子：多路并发服务中，权重显存减半直接提升可驻留路数，假设原 BF16 下单卡可驻留 N 路，INT8 后权重占用减半，可驻留路数上升，但上升幅度受激活工作区与 KV 配比限制，实际路数由 <span class=\"formula\">$$\\text{路数} = \\left\\lfloor \\frac{M_{\\text{card}} - M_{\\text{act}} - M_{\\text{kv}}}{M_{W,\\text{INT8}} + M_{W,\\text{BF16,branch}}} \\right\\rfloor$$</span> 决定，其中分母同时含 INT8 与高精度分支权重。这说明第三档比例是并发路数的直接杠杆。</p>\n\n<h3 id=\"alg-codec-int8-quant-sec-31\">三十一 · 调度参数：批、实时率与 SLO 的三角</h3>\n<p>调度参数在 INT8 配方里不是独立调优项，而是被量化档位反向约束的。连续批处理下，批大小受 INT8 激活显存与混合精度分支影响：同一 batch 内若混入走 BF16 分支的请求，整个 batch 的 epilogue 路径要按最慢分支对齐，吞吐收益被拉平。配方做法是按量化档位分池调度——全 INT8 请求进高吞吐池，含高精度分支的请求进低延迟池，两池共享权重但独立组批。</p>\n<p>SLO 以吞吐与实时率为约束。实时率（RTF）要求单次前向延迟低于音频块时长，INT8 矩阵乘吞吐翻倍给的是吞吐余量而非单请求延迟下降，因为反量化与平滑缩放都在关键路径上。配方里把 per-channel 激活量化的 epilogue 开销按层实测：若某卷积层本身已受带宽限制，epilogue 额外反量化会让端到端吞吐不升反降，这类层退回 per-tensor 激活量化。这是“按层实测而非全局套用”的具体落点。</p>\n<p>具体例子：流式编解码器分块推理场景下，块时长固定，调度器按块截止时间倒排优先级；INT8 池可以把每卡并发路数抬高，但每块的 epilogue 开销必须计入块预算，否则高并发下块截止时间被击穿，表现为实时率抖动而非平均吞吐下降。</p>\n\n<h3 id=\"alg-codec-int8-quant-sec-32\">三十二 · 可复现配置思路的落地顺序</h3>\n<p>给出可复现路径，顺序不能颠倒。第一步固定硬件档位与并行拓扑：单卡多路优先，TP 仅在显存不足时启用，并把高精度分支钉在单卡。第二步做层敏感度分析：用校准集统计各层权重与激活动态范围，按误差上界公式排序，圈出必须保留 FP16/BF16 的层（输出投影、RVQ 码本、波形重建末段）。第三步对剩余层做平滑加 per-channel 权重 INT8，激活先 per-tensor，再对动态范围波动大的层试 per-channel 并实测 epilogue 开销。第四步按档位分池组批，设定批大小上限与实时率约束。第五步校准集覆盖度验收：校准集需覆盖目标说话人与音频内容分布，只覆盖单一说话人或单一语种会让动态范围估计偏窄，上线遇高能量音频时 INT8 饱和削波，输出爆音与失真。</p>\n<p>这套顺序的代价是前期层敏感度分析与校准集建设的时间投入，收益是 PTQ 无需重训练、适合已训练好的编解码器快速部署。规模上限受混合精度分支比例与校准集覆盖度制约：极低比特（如 INT4）在 RVQ 码本与输出层上失真明显，配方应把 INT4 排除在码本与输出层之外，边缘场景需按内容自适应校准而非一套校准集通吃。</p>\n<p>最后一段落在具体机制上：配方文档里每个卷积层应携带三个字段——量化档位、平滑因子 α、激活量化粒度（per-tensor 或 per-channel），调度器按档位字段组批、按粒度字段决定 epilogue 路径。这三个字段构成从校准到上线的可复现契约，任何一层缺字段都意味着该层未被实测，不能进入生产配置。</p>\n\n<h3 id=\"alg-codec-int8-quant-sec-33\">三十三 · 配方失效的三种边界：校准漂移、敏感层误伤与 epilogue 反噬</h3>\n\n<p>这套部署配方的骨架是：权重 per-channel INT8、激活经 SmoothQuant 式通道平滑后量化、卷积与线性层走 INT8 Tensor Core、反量化在 epilogue 完成，输出投影与 RVQ 码本查找保留 BF16 分支。它的收益来自权重显存减半与 INT8 矩阵乘吞吐约为 BF16 的两倍，代价则集中在三个边界上，而这三个边界恰好是配方从“能跑”滑向“不能上线”的分水岭。第一个边界是校准集覆盖度。量化误差的上界由 <span class=\"formula\">$$\\text{err} \\le \\frac{\\Delta_W \\|X\\| + \\Delta_X \\|W\\|}{2}$$</span> 给出，其中 $\\Delta_X$ 直接由校准集统计出的激活动态范围决定。若校准集只覆盖单一说话人或单一语种，$\\Delta_X$ 被估窄，上线后遇到高能量音频，INT8 饱和削波，输出表现为爆音与失真——这不是精度缓慢退化，而是硬削顶，听感上不可接受。工程判断是：校准集必须按目标说话人、语种、采样率与内容类型分层采样，且把每层的激活最大绝对值分位数（而非全局最大值）作为 $\\Delta_X$ 的估计量，留出饱和余量。</p>\n\n<p>第二个边界是敏感层的识别粒度。RVQ 码本查找与输出投影对量化敏感，若被一并纳入 INT8 而未保留高精度分支，码本索引错位会产生音素级噪声，这种噪声在语音可懂度指标上可能不明显，但人耳一听即辨。配方里“按层敏感度分析强制保留 FP16/BF16”不能停留在定性描述，落地做法是对每层做单层量化消融：仅将该层降为 INT8、其余保持 BF16，测其输出与全精度分支的谱失真或梅尔倒谱距离，超过阈值的层进入高精度白名单。混合精度分支的比例直接决定规模上限——白名单越长，权重显存减半的收益被侵蚀得越多，调度复杂度也随分支切换上升。可复现的配置思路是把白名单比例作为显式旋钮：先按敏感度排序取前若干层，再在吞吐与音质之间做二分。</p>\n\n<p>第三个边界最容易被忽略：per-channel 激活量化在 epilogue 引入额外反量化与缩放开销。当卷积层本身已受显存带宽限制时，epilogue 的逐通道缩放会把这部分省下的带宽重新吃掉，端到端吞吐不升反降。判断依据是层级的算术强度：权重与激活压到 INT8 后，若该层的字节访问量下降幅度不足以抵消 epilogue 的额外指令与寄存器压力，INT8 就只带来精度损失而无吞吐收益。因此配方必须按层实测而非全局套用，把“per-tensor 激活 + per-channel 权重”作为默认档，仅在实测证明 per-channel 激活有净收益的层上启用。下表给出三档配置的取舍边界，硬件档位统一为 Blackwell Tensor Core GPU 或边缘推理芯片，并行拓扑按单卡多路并发组织，调度参数以实时率为硬约束、批大小为软旋钮。</p>\n\n<table class=\"mini\"><thead><tr><th>档位</th><th>量化方案</th><th>KV/状态策略</th><th>失效条件</th></tr></thead><tbody><tr><td>保守档</td><td>权重 INT8 per-channel，激活 BF16</td><td>状态缓存 BF16，按路数静态分配</td><td>显存收益仅一半，并发路数提升有限</td></tr><tr><td>默认档</td><td>权重 INT8，激活 per-tensor INT8，敏感层 BF16</td><td>状态缓存 INT8，动态扩容</td><td>校准集偏差时饱和削波；白名单过长则收益衰减</td></tr><tr><td>激进档</td><td>权重与激活均 per-channel INT8</td><td>状态缓存 INT8，按内容自适应</td><td>epilogue 反噬，带宽受限层吞吐不升反降</td></tr></tbody></table>\n\n<p>三档之间不是精度阶梯而是代价阶梯：保守档牺牲显存收益换稳定，激进档赌 epilogue 开销可被 INT8 带宽节省覆盖，默认档是唯一在多数编解码器与声码器卷积层上可复现的起点。配方与相邻算法正交——量化作用于卷积层本身，不改变声码器分块流式上采样策略，也不改变非自回归时长预测的步数结构，因此它可以独立叠加在这两者之上而不引入新的时序耦合。真正需要盯住的是极低比特的天花板：INT4 在 RVQ 码本与输出层上失真明显，PTQ 无需重训练的便利不能延伸到 4 比特，规模上限由混合精度分支比例与校准集覆盖度共同锁定。上线前的验收动作应是分层消融加分层实测吞吐，而非整模型一次性切换。</p>\n<h3 id=\"alg-codec-int8-quant-sec-34\">三十四 · 显存驻留与并发路数：权重减半不等于路数翻倍</h3>\n<p>INT8 权重量化对编解码器服务最直接的账面收益是权重显存减半，但并发路数并不按这个比例线性增长。原因是权重只是一次性常驻的静态部分，而每路请求的激活、KV 类中间张量、分块缓冲、混合精度分支的 FP16/BF16 副本都是随批大小与路数增长的动态部分。设单路动态显存为 $M_{\\text{act}}$、静态权重为 $W_{\\text{bf16}}$、量化后为 $W_{\\text{int8}}$、敏感层保留高精度比例为 $\\rho$，则可驻留路数近似为</p>\n<div class=\"formula\">$$N_{\\max} \\approx \\frac{M_{\\text{GPU}} - W_{\\text{bf16}}\\cdot\\rho - W_{\\text{int8}}\\cdot(1-\\rho)}{M_{\\text{act}} + M_{\\text{branch}}}$$</div>\n<p>其中 $M_{\\text{branch}}$ 是混合精度分支额外占用的中间缓冲。这个式子说明：当 $\\rho$ 上升（比如 RVQ 码本查找与输出投影整层保留 BF16），静态节省被吃掉一部分；当 $M_{\\text{act}}$ 随分块长度和批大小增长，分母主导，权重减半带来的路数增益被稀释。工程判断是先把 $\\rho$ 压到最小必要集合，再按层实测激活峰值，而不是拿“权重减半”直接外推并发能力。一个具体例子：声码器上采样卷积层权重占静态显存主体，量化后单卡可驻留路数上升，但若把输出投影与码本查找整段保留 BF16，且每路分块缓冲按最长音频预留，实际路数增益远小于二倍，容量规划必须按实测峰值而非理论值做。</p>\n\n<h3 id=\"alg-codec-int8-quant-sec-35\">三十五 · 带宽与算术强度：INT8 把瓶颈从算力推向访存</h3>\n<p>Blackwell Tensor Core 上 INT8 矩阵乘吞吐约为 BF16 的两倍，但编解码器卷积层的算术强度并不高：小通道数、短卷积核、逐层反量化与缩放都在拉低每字节访存对应的乘加数。设某层乘加数为 $2MNK$、字节流量为 $(M K + K N)\\cdot b$，$b$ 为每元素字节数，算术强度为</p>\n<div class=\"formula\">$$I = \\frac{2MNK}{(MK + KN)\\cdot b}$$</div>\n<p>权重从 2 字节降到 1 字节使 $b$ 下降，$I$ 上升，理论上更靠近算力上限；但 epilogue 的反量化、per-channel 缩放、激活重新量化会引入额外读写，把节省的带宽又吐回去一部分。更关键的是，编解码器与声码器的许多层是带宽受限而非算力受限，此时 INT8 的吞吐收益取决于能否把反量化融进 epilogue 而不产生额外全局内存往返。具体机制上，权重 per-channel INT8 加载后在寄存器/共享内存侧完成缩放再进 Tensor Core，激活的 per-tensor 或 per-channel 量化在写回前完成，避免中间张量以 FP16 落盘。代价判断：若某层实测已处于带宽墙，per-channel 激活量化在 epilogue 增加的反量化与缩放开销会让端到端吞吐不升反降，这类层应退回 per-tensor 激活或直接保留 BF16，按层实测而非全局套用。</p>\n\n<h3 id=\"alg-codec-int8-quant-sec-36\">三十六 · 通信与多卡：权重量化改变的是切分账本</h3>\n<p>在多卡张量并行或流水并行下，INT8 权重改变的不只是单卡显存，还有集合通信的字节账本。权重 all-gather 或参数广播的字节数随位宽下降，但激活在并行边界上的传输仍是 BF16/FP16 精度（除非做激活量化通信，而这在编解码器上风险高）。设并行度为 $P$、每步权重同步字节为 $W\\cdot b/P$、激活通信字节为 $A\\cdot 2$，量化把第一项减半，第二项不变。当 $A$ 较大（长分块、大 batch 的声码器上采样中间张量），通信总量由激活主导，权重量化对通信时间的改善有限。工程上更现实的收益是把省下的显存换成更大的并行度或更大的批，用通信换吞吐。具体例子：NVL72 域内多卡部署编解码器时，权重切分后每卡静态占用下降，允许把更多层放进单卡以减少流水气泡，但跨卡激活同步的字节数不因量化而减少，尾延迟仍由最慢的那次激活集合通信决定，容量规划要把这部分单独建模。</p>\n\n<h3 id=\"alg-codec-int8-quant-sec-37\">三十七 · 功耗与热：吞吐翻倍不等于能效翻倍</h3>\n<p>INT8 矩阵乘在相同时间内完成两倍乘加，单次前向的算力能耗下降，但整机功耗由显存带宽、epilogue 反量化、混合精度分支切换、以及为压尾延迟而维持的高时钟共同决定。设单次前向能耗为 $E_{\\text{mac}} + E_{\\text{mem}} + E_{\\text{epi}}$，量化主要压缩 $E_{\\text{mac}}$ 与权重访存的 $E_{\\text{mem}}$，但 $E_{\\text{epi}}$ 因反量化与缩放而上升。当服务以实时率为约束、多路并发把 GPU 推到高利用率，功耗墙与热节流会成为规模上限的先崩点：算力还有余量，但持续高时钟不可维持，尾延迟在长时压测下抬升。工程判断是把 INT8 的吞吐收益部分兑换成降频运行而非满频堆批，用更低的时钟维持同等实时率，从能效角度换更稳的尾延迟。具体例子：多路并发声码器合成在满批时接近功耗上限，降批或降频后单路延迟略升但 P99 显著收敛，这种取舍在边缘与高密度机架场景比峰值吞吐更重要。</p>\n\n<h3 id=\"alg-codec-int8-quant-sec-38\">三十八 · 尾延迟：混合精度分支与校准偏差是两大来源</h3>\n<p>均值吞吐好看不代表 SLO 达标，编解码器 INT8 服务的尾延迟有两个结构性来源。其一是混合精度分支：RVQ 码本查找与输出投影保留 FP16/BF16，这些层与 INT8 层交替执行，调度器在两种精度间切换带来额外同步与流水气泡，批内若混有触发高精度路径的请求，整批被拖到最慢路径。其二是校准偏差：激活动态范围随音频内容波动，校准集只覆盖单一说话人或单一语种时动态范围估计偏窄，上线遇到高能量音频触发 INT8 饱和削波，输出爆音与失真，重试与回退逻辑进一步拉长尾延迟。量化误差上界为</p>\n<div class=\"formula\">$$\\text{err} \\le \\frac{\\Delta_W \\|X\\| + \\Delta_X \\|W\\|}{2}$$</div>\n<p>其中 $\\Delta_W$、$\\Delta_X$ 分别为权重与激活的量化步长。校准偏差直接放大 $\\Delta_X$，误差上界随音频能量上升而恶化，这正是尾延迟与音质同时崩的机制。缓解手段是按层敏感度分析强制保留高精度分支、按内容自适应校准、并对饱和层做运行时钳位与回退。代价是回退路径本身占用显存与调度槽位，容量规划需为回退预留余量，否则一次校准失配就把整机并发打回 BF16 水平。</p>\n\n<h3 id=\"alg-codec-int8-quant-sec-39\">三十九 · 规模上去先崩在哪里：按瓶颈排序的工程判断</h3>\n<p>把上述代价按规模放大后的敏感度排序，先崩的通常不是算力。第一是尾延迟：混合精度分支切换与校准偏差引发的回退在并发上升时被放大，P99 先破 SLO。第二是功耗与热节流：满批高时钟不可持续，长时压测下吞吐回落。第三是激活带宽与 epilogue 开销：per-channel 激活量化在带宽受限层上反噬吞吐。第四才是显存容量：权重减半确实推迟了显存墙，但只要 $\\rho$ 与分块缓冲没压住，显存仍会在高路数时成为硬约束。工程判断是把优化预算按这个顺序投：先做敏感层最小化与校准集覆盖度，再做 epilogue 融合与按层精度选择，最后才用省下的显存换并发。规模上限受混合精度分支比例与校准集覆盖度制约，边缘场景需按内容自适应校准；极低比特（如 INT4）在 RVQ 码本与输出层上失真明显，不应作为规模扩展的手段。真正决定规模的是“每路动态显存 × 回退余量 × 尾延迟裕度”这三项的乘积，而不是权重位宽本身。</p>\n\n<h3 id=\"alg-codec-int8-quant-sec-40\">四十 · 规模上去以后，先崩的是带宽与混合精度分支的调度</h3>\n<p>把编解码器与声码器的卷积、线性层压到 INT8，单卡单路的收益是线性的：权重显存减半，INT8 矩阵乘吞吐约为 BF16 的 2 倍，反量化被推到 epilogue，主循环里只剩 Tensor Core 的整数乘加。但规模上去之后，崩溃点不在算力，而在两个地方——激活的读写带宽，以及混合精度分支带来的调度碎片。前者由量化误差公式直接决定：<div class=\"formula\">$$\\text{err} \\le \\frac{\\Delta_W \\|X\\| + \\Delta_X \\|W\\|}{2}$$</div>权重 per-channel 量化把 $\\Delta_W$ 压得很小，误差项就主要由 $\\Delta_X \\|W\\|$ 主导，也就是激活动态范围估计的精度。多路并发时每路音频内容不同，激活的 per-tensor 缩放因子若按批共享，$\\Delta_X$ 会被批内最响的那一路撑大，安静路的信噪比被牺牲；若改成 per-channel 激活量化，epilogue 就要为每个通道做一次反量化与缩放，这部分开销在卷积本身已经受带宽限制时会吃掉全部吞吐收益，端到端不升反降。</p>\n<p>显存账要按驻留路数算，而不是按单路算。权重减半释放出的显存直接换成并发路数，但激活显存并不等比下降——INT8 激活只省了存储宽度，中间特征图的峰值占用仍由批大小与分块策略决定，声码器上采样阶段的高分辨率特征图尤其如此。真正决定上限的是混合精度分支的比例：输出投影、RVQ 码本查找这类敏感层保留 FP16/BF16，它们在图中形成不连续的精度断点，每个断点都要一次格式转换与同步。批内路数越多，这些断点上的 kernel launch 与同步次数越密，调度器在 INT8 与 BF16 两条流水间切换的间隙就成为尾延迟的来源。尾延迟不体现在平均吞吐上，而体现在 P99：某一路恰好落在需要高精度分支的层上，等待同批其他路完成 INT8 段，排队时间被放大。</p>\n<p>通信侧的压力来自分离式部署。预填与解码分离后，编解码器往往作为独立服务挂在解码端之前或之后，INT8 权重让单副本显存变小，副本数可以变多，但每路请求的激活张量仍要在 NVLink 或网络上来回搬运。权重减半并不减少激活流量，反而因为副本增多、路由更碎，集合通信的固定开销占比上升。功耗维度上，INT8 Tensor Core 的单位算力能效优于 BF16，但混合精度分支让 SM 在两种指令流间反复切换，占用率被切碎，能效收益被摊薄；边缘芯片上这一效应更明显，因为边缘场景的功耗预算本来就紧，调度开销占比更高。</p>\n<table class=\"mini\"><thead><tr><th>规模变量</th><th>先崩的位置</th><th>工程判断</th></tr></thead><tbody><tr><td>并发路数上升</td><td>激活带宽与 epilogue 反量化</td><td>按层实测 per-channel 激活是否值得</td></tr><tr><td>批大小上升</td><td>混合精度断点的同步间隙</td><td>把敏感层集中排布，减少切换次数</td></tr><tr><td>副本数上升</td><td>集合通信固定开销</td><td>合并小请求，降低路由碎片</td></tr><tr><td>内容分布漂移</td><td>校准集偏差导致饱和削波</td><td>按说话人与语种扩充校准集</td></tr></tbody></table>\n<p>失效条件很具体：校准集只覆盖单一说话人或单一语种，激活动态范围估计偏窄，上线后遇到高能量音频时 INT8 饱和削波，输出出现爆音与失真；RVQ 码本查找与输出投影被一并量化而未保留高精度分支，码本索引错位导致音素级噪声。规模上限因此不由比特数决定，而由混合精度分支比例与校准集覆盖度共同约束——分支比例越高，调度碎片越多；覆盖度越窄，$\\Delta_X$ 越不可信。工程上的判断是：先按层做敏感度分析固定高精度白名单，再对剩余层逐层实测 per-channel 激活的 epilogue 开销，只有当该层确实受权重带宽限制时才启用，而不是全局套用。</p>\n<h3 id=\"alg-codec-int8-quant-sec-41\">四十一 · 校准集偏差引发的饱和削波与爆音</h3>\n<p>INT8 编解码器最隐蔽的失效不是权重错了，而是激活的量化刻度错了。per-tensor 激活量化只保留一个全局缩放因子 $s_X$，一旦校准集只覆盖单一说话人、单一语种或安静录音，统计出的 $\\max(|X|)$ 偏窄，上线后遇到高能量音频（近讲、爆破音、音乐瞬态），激活值直接越过 INT8 的 $[-127,127]$ 边界被截断，反量化后波形出现硬削波，听感上是爆音与持续失真。这不是随机噪声，而是与音频包络强相关的周期性失真，用户投诉往往集中在“大声说话就破音”。</p>\n<p>诊断的关键是把“饱和率”做成一级指标，而不是等主观听测发现问题。在 epilogue 反量化前插入一个极轻量的计数器，统计每层激活张量中落在 $|x| &gt; 127 \\cdot s_X$ 之外的元素比例，按层、按请求、按音频能量分桶上报。健康状态下该比例应贴近零；一旦某层饱和率随输入能量单调上升，即判定为校准集覆盖不足。工程上更省的做法是在校准阶段直接记录每层激活的分位数（如 99.9% 分位与最大值之比），比值过大说明分布长尾，per-tensor 缩放不适合该层，应改为 per-channel 或对该层保留 BF16。</p>\n<p>代价面很直接：饱和削波不增加延迟，但会把一次请求的音频质量判为不合格，等于把吞吐收益全部作废；而修法——扩校准集或改 per-channel——会增加 epilogue 的反量化与缩放指令数，per-channel 激活量化在卷积已受带宽限制时会让端到端吞吐不升反降。具体例子：某层卷积输出通道的动态范围相差两个数量级，per-tensor 缩放被迫按最大通道定标，其余通道有效位只剩五六比特，表现为本底噪声抬升；改成 per-channel 后噪声回落，但 epilogue 多出逐通道乘加，需按层实测收益。</p>\n\n<h3 id=\"alg-codec-int8-quant-sec-42\">四十二 · 敏感层误量化：码本索引错位与音素级噪声</h3>\n<p>RVQ 码本查找与输出投影是整条链路上对量化最不容忍的两处。码本查找本质是离散索引的最近邻选择，量化误差会把某个码矢推到相邻码矢的判决边界之外，解码端拿到的索引整体错位，合成音频出现音素级、音节级的规律性噪声，而非平滑的量化噪声。输出投影直接决定波形或特征的最后一层线性组合，其权重误差不经后续层稀释，会以直流偏移或高频毛刺的形式直达输出。失败模式很明确：把这两类层与普通卷积一并 INT8 化、未做逐层敏感度分析、未强制保留 FP16/BF16 分支。</p>\n<p>诊断手段是逐层敏感度扫描：在校准集的一个小子集上，每次只把一层从 INT8 切回 BF16，测量输出与全精度基线的偏差（特征域用余弦相似度或 SNR，波形域用尺度不变信噪比），得到一张“层—偏差”排序表。偏差在切回高精度后骤降的层即为敏感层，必须进混合精度白名单。这一步不需要重训练，代价是一次离线扫描的算力，换来的是上线后不再出现索引错位。</p>\n<p>系统代价体现在混合精度分支的调度复杂度：白名单层要走 BF16 路径，意味着 kernel 选择、张量布局与 epilogue 都要分叉，同一 batch 内不同层走不同精度会打断融合，增加启动开销与显存碎片。但保留高精度分支换来的是码本索引稳定，这是不可交易的。工程判断是：白名单只放真正敏感的少数层，比例失控会吃掉 INT8 的显存与吞吐收益；用敏感度表定量决定边界，而不是凭经验全局保留。</p>\n\n<h3 id=\"alg-codec-int8-quant-sec-43\">四十三 · 显存与批抖动：混合精度分支下的 OOM 与批形震荡</h3>\n<p>INT8 把权重显存减半，理论上直接提升可驻留并发路数，但混合精度分支让这个账不干净。BF16 白名单层不参与减半，激活侧还要为 per-channel 缩放因子、反量化临时缓冲留出空间；更麻烦的是变长音频导致批内序列长度不齐，padding 到最长样本会放大激活显存峰值，出现“平均显存够、峰值显存不够”的 OOM。这类 OOM 往往不是稳态发生，而是在某个长音频请求混入批时突然触发，表现为偶发、难复现。</p>\n<p>批抖动的机制是调度器按显存余量动态调批大小，而显存余量本身随批内内容波动：一个高能量、长时长的样本抬高激活峰值，调度器缩批，吞吐掉下去；下一批全是短样本，显存余量回升，批又放大。批大小在时间轴上震荡，吞吐曲线呈锯齿状，实时率约束被反复触碰。诊断要看两个量：批大小的方差，以及每批激活显存峰值与均值的比值。前者大说明调度策略对内容过于敏感，后者大说明 padding 或峰值缓冲设计有问题。</p>\n<p>缓解手段按代价排序：其一，按音频时长分桶再组批，牺牲一点批内多样性换取显存可预测；其二，为激活峰值预留固定 headroom，代价是牺牲一部分可驻留路数；其三，对超长样本走单独的小批通道，避免污染主批。三者都会让吞吐略降，但换来的是尾延迟可预测。具体例子：同一批里混入一条数倍于均值的长音频，padding 后激活显存峰值抬升，触发调度器缩批，后续若干短请求被迫排队，尾延迟尖刺由此产生——根因不在算力，而在批形。</p>\n\n<h3 id=\"alg-codec-int8-quant-sec-44\">四十四 · 路由不均与尾延迟尖刺</h3>\n<p>多路并发服务里，INT8 编解码器常按层或按模块拆到不同执行单元，混合精度分支进一步加剧不均衡：走 BF16 的敏感层单次前向耗时高于 INT8 层，若调度按请求数而非按计算量分配，BF16 密集的副本会持续积压，形成路由不均。表现是整体平均延迟正常，但 P99 尾延迟出现尖刺，且尖刺集中在少数副本上。诊断要把每副本的在途请求数、队列等待时间、按层耗时分解同时上报，看尖刺是否与 BF16 层耗时占比相关。</p>\n<p>尾延迟尖刺还有第二个来源：per-channel 激活量化的 epilogue 开销在批较大时被放大，反量化与缩放的指令数随批内元素线性增长，当卷积本身已接近带宽上限，epilogue 成为新的瓶颈，批越大单批耗时非线性上升。此时增大批反而恶化尾延迟。判断依据是对比不同批大小下的单批耗时曲线，若出现上翘拐点，说明 epilogue 已主导。</p>\n<p>工程对策是分层限流而非全局限流：对 BF16 敏感层所在的执行路径单独设并发上限，把尖刺隔离在局部；对 epilogue 重的层限制批内元素总数而非请求数。代价是资源利用率下降，换来的是 SLO 可守。具体例子：某副本因承载了较多含 RVQ 码本查找的请求，BF16 分支耗时占比高，队列持续偏长，P99 被拉高；把该副本的并发上限下调、把部分请求路由到 INT8 占比更高的副本后，尾延迟回落，平均吞吐仅小幅下降。</p>\n\n<h3 id=\"alg-codec-int8-quant-sec-45\">四十五 · 监控指标与回滚判据</h3>\n<p>监控要覆盖三层：数值层、资源层、体验层。数值层盯每层饱和率、敏感层偏差（离线表与在线抽样比对）、码本索引分布偏移；资源层盯激活显存峰值/均值比、批大小方差、epilogue 耗时占比、每副本队列等待；体验层用可自动化的代理指标替代主观听测，如波形尺度不变信噪比相对全精度基线的下降幅度、静音段本底噪声能量。三层指标要能按请求、按层、按副本下钻，否则定位不到根因。</p>\n<p>回滚判据要预先写死，不靠临场判断。给出可执行的阈值逻辑：当某层饱和率连续多个统计窗口超过设定上限，或敏感层在线抽样偏差超过离线基线的一定倍数，或尾延迟 P99 连续越界且定位到混合精度分支，则触发回滚。回滚粒度应是按层而非整体：把出问题的层从 INT8 切回 BF16，保留其余层的量化收益，比整体退回 BF16 的代价小得多。整体回滚只作为最后手段，用于校准集整体失效的场景。</p>\n<p>回滚本身也有代价：切层会改变 kernel 选择与显存布局，需要重建执行计划，短时吞吐下降；若白名单层比例上升，权重显存回升，可驻留路数下降，容量规划要预留这部分余量。工程判断是把“量化配置”当作可版本化的部署参数，与校准集版本、敏感层白名单绑定，任何一次上线都记录三元组，回滚时按版本切换而非手工改层，避免配置漂移。公式上，量化误差上界 $\\text{err} \\le \\frac{\\Delta_W \\|X\\| + \\Delta_X \\|W\\|}{2}$ 提醒我们：$\\Delta_X$ 由校准集决定，$\\Delta_W$ 由 per-channel 缩放决定，两者任一失控都会让误差上界抬升，监控就是盯住这两个量的实际取值是否偏离部署时的假设。</p>\n<p>最后落到一个具体机制上：把敏感层白名单、校准集版本、每层缩放因子快照打包成不可变的量化制品，推理服务启动时校验制品哈希，运行时按层上报饱和率与偏差，越界即按制品回退到上一个已知良好版本。这条链路让“精度问题、OOM、批抖动、路由不均、尾延迟尖刺”五类失败都有确定的观测点和确定的退路，而不是靠人盯日志猜。</p>\n\n\n<h3 id=\"alg-codec-int8-quant-sec-46\">四十六 · 量化上线的暗礁：从校准漂移到混合精度分支的调度代价</h3>\n<p>INT8 编解码器最隐蔽的失效不在权重侧，而在激活侧。per-channel 权重缩放是离线算好的，稳定；激活动态范围却随音频内容实时漂移。校准集若只覆盖单一说话人或单一语种，$s_X$ 被估窄，上线遇到高能量瞬态（爆破音、近场录音、音乐段落）时 INT8 直接饱和削波，误差项 $\\Delta_X\\|W\\|/2$ 被放大成可闻的爆音与失真。诊断手段是把每层激活的饱和比例当作一等指标：在 epilogue 反量化前统计被 clamp 到 ±127 的样本占比，超过阈值即判定该层校准失效，而不是等主观听测发现问题。这类指标必须按内容切片（说话人、语种、采样率、信噪比）分别聚合，全局均值会把窄分布校准集的偏差完全掩盖。</p>\n<p>第二类失效是敏感层误伤。RVQ 码本查找与输出投影一旦被一并量化而未保留 FP16/BF16 分支，码本索引错位会产生音素级噪声——它不是音量或音色偏差，而是结构性错误，任何后处理都救不回来。工程判断是：按层做敏感度分析，对码本索引路径与输出投影强制走混合精度，其余卷积层吃 INT8。代价是调度复杂度上升：一个 kernel launch 序列里混着 INT8 Tensor Core 路径与 BF16 路径，批内不同请求若命中不同精度分支，批调度器要按分支拆批，批大小受最慢分支的显存与算力约束，批抖动随之出现。监控上应记录每批的精度分支构成与有效批大小方差，方差抬升即是拆批过碎的信号。</p>\n<p>第三类失效是收益反转。per-channel 激活量化在 epilogue 引入逐通道反量化与缩放开销，若该卷积层本身已受显存带宽限制而非算力限制，端到端吞吐不升反降。判据不能靠全局套用，要按层实测：比较该层 INT8 与 BF16 的实测耗时，只有算力受限层才值得开 per-channel 激活。尾延迟尖刺通常来自这里——多数请求走快路径，少数命中重反量化层的请求拖长 P99。回滚策略应做成层粒度的精度开关而非整模型回退：保留一份 BF16 权重影子副本用于快速切换，同时以校准集覆盖度与饱和比例为触发条件自动降级敏感层。路由不均则表现为多路并发下部分实例命中高能量音频而饱和、部分空闲，需在入口按内容特征做轻量分流，把校准分布外的请求导向高精度实例。</p>\n<table class=\"mini\"><thead><tr><th>失效模式</th><th>可观测指标</th><th>回滚动作</th></tr></thead><tbody><tr><td>激活饱和削波</td><td>逐层 clamp 占比、按内容切片</td><td>重校准或该层切 BF16</td></tr><tr><td>码本索引错位</td><td>码本路径精度分支命中率</td><td>强制保留 FP16/BF16 分支</td></tr><tr><td>epilogue 反量化过重</td><td>逐层 INT8/BF16 实测耗时比</td><td>关闭该层 per-channel 激活</td></tr><tr><td>批抖动与尾延迟</td><td>有效批大小方差、P99 分支构成</td><td>按分支拆批阈值调优</td></tr></tbody></table>\n<h3 id=\"alg-codec-int8-quant-sec-47\">四十七 · 同族算法的坐标：量化作用点与步数结构</h3>\n<p>把编解码器 INT8 权重量化放进同族算法谱系，先要回答一个坐标问题：它改变的是哪一层代价。流式编解码器分块推理改变的是时间轴切分，残差矢量量化流式解码改变的是码本层级的展开顺序，自回归码本 LM 投机解码改变的是每步生成的候选结构，非自回归时长预测批推理改变的是并行度与批形状。INT8 量化与它们全部正交——它不改变分块策略、不改变 RVQ 层级展开、不改变步数结构，只压缩卷积与线性层的权重与激活位宽。这意味着选型时它几乎从不与上述算法互斥，而是一个可叠加的乘数项；真正需要做取舍的，是同族中另外两类同样作用于“数值精度”的算法：微缩放格式（MXFP/NVFP4 一类块缩放）编解码器推理，以及 ASR 低比特量化边缘推理所代表的更激进位宽路线。三者共享“校准—缩放—量化—反量化 epilogue”的骨架，分歧在于缩放粒度、位宽下限与敏感层处理方式。</p>\n<p>工程判断的第一条：先看瓶颈落在权重带宽还是激活带宽。编解码器与声码器的卷积层权重常驻显存，多路并发时权重被反复读取，权重带宽是主项；此时 per-channel INT8 权重压缩直接把驻留路数抬高，收益线性可预期。若瓶颈在激活侧——长音频分块导致激活张量随块数增长——则单纯权重量化不够，必须配合激活平滑与 per-channel 激活量化，代价是 epilogue 开销。第二条：看敏感层占比。RVQ 码本查找与输出投影必须保留 FP16/BF16，混合精度分支比例越高，INT8 的理论吞吐收益被稀释得越多；当敏感层占比超过某个经验阈值，端到端收益会被调度切换开销吃掉。</p>\n\n<h3 id=\"alg-codec-int8-quant-sec-48\">四十八 · 决策表：四条路线的适用条件</h3>\n<p>下表把同族四条路线放在同一组判据下对照，判据全部是可观测的工程量，而非抽象优劣。</p>\n<table class=\"mini\">\n<thead>\n<tr><th>路线</th><th>作用点</th><th>位宽/粒度</th><th>敏感层处理</th><th>主要代价</th><th>适用条件</th></tr>\n</thead>\n<tbody>\n<tr><td>INT8 PTQ（本条目）</td><td>卷积/线性层权重+激活</td><td>权重 per-channel，激活 per-tensor 或 per-channel</td><td>输出投影、RVQ 码本保留 FP16/BF16</td><td>混合精度调度复杂度、epilogue 反量化</td><td>已训练模型快速部署；权重带宽受限；校准集可覆盖目标分布</td></tr>\n<tr><td>微缩放格式（块缩放）</td><td>权重为主，块内共享缩放</td><td>小块共享指数，位宽更低</td><td>同样需高精度旁路</td><td>块缩放元数据与解包开销</td><td>权重带宽极端受限、可接受块级精度损失</td></tr>\n<tr><td>ASR 低比特边缘路线</td><td>整网含激活</td><td>更低比特，常配量化感知训练</td><td>按层敏感度强制保留</td><td>需重训练或精细校准</td><td>边缘功耗与显存硬约束；有训练侧配合</td></tr>\n<tr><td>仅权重量化（W8A16）</td><td>仅权重</td><td>权重 INT8，激活保持 BF16</td><td>无需混合分支</td><td>激活带宽未减，吞吐增益有限</td><td>激活动态范围极不稳定、校准风险高的场景</td></tr>\n</tbody>\n</table>\n<p>读表的关键在于“仅权重量化”这一行常被忽略：当激活动态范围随音频内容剧烈波动、校准集又难以覆盖全部说话人与语种时，W8A16 是风险最低的退路——权重显存减半、驻留路数提升，但不引入激活饱和削波的风险，也不需要在 epilogue 做激活反量化。它的吞吐增益小于完整 INT8 矩阵乘，但在爆音不可接受的语音产品里，这个折中是理性的。反之，若服务侧以多路并发吞吐为硬 SLO、且校准集能覆盖目标内容分布，完整 INT8 才是正确选择。</p>\n\n<h3 id=\"alg-codec-int8-quant-sec-49\">四十九 · 判据的量化表达：收益与风险的边界</h3>\n<p>选型不能停留在定性对照，需要把“收益是否被代价吃掉”写成可计算的不等式。设单层卷积的权重字节数为 $B_W$、激活字节数为 $B_X$，INT8 后分别为 $B_W/2$、$B_X/2$（相对 BF16）。端到端时间近似为</p>\n<div class=\"formula\">$$T \\approx \\max\\left(\\frac{B_W+B_X}{\\text{BW}},\\ \\frac{\\text{FLOPs}}{\\text{Peak}_{\\text{INT8}}}\\right) + T_{\\text{epi}} + T_{\\text{mix}}$$</div>\n<p>其中 $T_{\\text{epi}}$ 是 per-channel 激活反量化与缩放在 epilogue 的开销，$T_{\\text{mix}}$ 是混合精度分支的调度切换开销。INT8 矩阵乘吞吐约为 BF16 的 2 倍，因此第二项减半；但若第一项本就受带宽限制且 $T_{\\text{epi}}$ 随通道数线性增长，则端到端可能不升反降——这正是失败模式中“per-channel 激活量化在 epilogue 引入额外开销、卷积已受带宽限制时吞吐不升反降”的算术根源。工程上应逐层实测 $T_{\\text{epi}}$ 与带宽占比，而不是全局套用同一套量化配置。</p>\n<p>误差侧同样有边界。量化误差上界为</p>\n<div class=\"formula\">$$\\text{err} \\le \\frac{\\Delta_W \\|X\\| + \\Delta_X \\|W\\|}{2}$$</div>\n<p>平滑变换 $\\hat{x}=x\\cdot s,\\ \\hat{W}=W/s$ 的作用是把 $\\Delta_X$ 与 $\\Delta_W$ 的相对量级拉平，使两项误差贡献均衡；若校准集只覆盖单一说话人或单一语种，$\\Delta_X$ 被低估，上线遇到高能量音频时 INT8 饱和削波，误差上界被实际突破，表现为爆音与失真。因此校准集覆盖度不是“尽量好”的软要求，而是决定误差上界是否成立的前提条件。敏感层的处理则是把该层的 $\\Delta$ 直接置零——保留 FP16/BF16 等价于承认该层不满足上述上界，用精度换音质。</p>\n\n<h3 id=\"alg-codec-int8-quant-sec-50\">五十 · 具体例子：三条路线的分岔判断</h3>\n<p>设想一个多路并发的编解码器服务：卷积层权重常驻显存构成主要带宽压力，RVQ 码本查找与输出投影对量化敏感，音频内容涵盖多说话人与多语种。判断路径如下。第一步，测权重带宽占比：若权重读取时间显著高于激活读取时间，权重量化是首选杠杆。第二步，评估校准集覆盖度：若目标说话人与语种可枚举且校准集能覆盖，走完整 INT8（权重 per-channel、激活 per-channel 加平滑）；若覆盖度不足，退到 W8A16，先拿权重显存减半的确定性收益。第三步，统计敏感层占比：把输出投影与 RVQ 码本强制保留 FP16/BF16，其余层 INT8；若敏感层占比使 $T_{\\text{mix}}$ 超过吞吐收益，则改为按块分组、把混合精度分支集中到少数连续层，减少切换次数。</p>\n<p>对照另两条路线：若显存约束极端、且能接受块级精度损失，微缩放格式以更低位宽换取更大驻留路数，代价是块缩放元数据解包；若场景是边缘设备、功耗与显存双重硬约束且有训练侧配合，ASR 低比特路线所代表的量化感知训练路径能把位宽压得更低，但 PTQ 的“无需重训练、快速部署”优势随之丧失。三条路线的分岔点不在算法优劣，而在“是否允许重训练”“校准集能否覆盖”“敏感层占比是否可承受”这三个可回答的问题上。</p>\n\n<h3 id=\"alg-codec-int8-quant-sec-51\">五十一 · 与正交算法的叠加次序</h3>\n<p>INT8 量化与分块流式、RVQ 渐进解码、非自回归并行合成等算法正交，但叠加有次序讲究。分块流式改变的是每次前向的输入形状与块数，量化改变的是每次前向内部的计算位宽；两者叠加时，应先确定分块策略再定校准集——因为分块边界影响激活的动态范围统计，若先量化后改分块，校准集统计的激活分布与实际推理分布错位，$\\Delta_X$ 估计失效。同理，与非自回归时长预测并行合成叠加时，量化只影响单次前向的吞吐与显存，不改变步数结构，因此批大小可以按 INT8 激活显存重新上调，但上调幅度受混合精度分支的显存占用制约——敏感层保留 BF16 意味着这部分显存不随量化减半，批大小上限由“INT8 层显存 + BF16 敏感层显存”共同决定，而非简单翻倍。</p>\n<p>与投机解码类算法叠加时需注意：投机解码的收益来自候选验证的并行度，量化压缩了单次前向的时间，但若验证阶段的敏感层（输出投影）保留高精度，验证路径的延迟下降幅度小于主干路径，投机收益的相对比例会被改变。这不是量化本身的问题，而是叠加后需要重新测算投机窗口大小的信号。</p>\n\n<h3 id=\"alg-codec-int8-quant-sec-52\">五十二 · 规模上限与工程落点</h3>\n<p>本路线的规模上限由两个量共同约束：混合精度分支比例与校准集覆盖度。前者决定吞吐收益的稀释程度——敏感层占比越高，INT8 矩阵乘覆盖的 FLOPs 比例越低，端到端加速比越接近 1；后者决定误差上界是否在实际流量下成立——覆盖度不足时，上线后的高能量音频会突破校准阶段估计的 $\\Delta_X$，饱和削波直接表现为可听见的爆音。极低比特（如 INT4）在 RVQ 码本与输出层上失真明显，因此位宽下探的天花板不在卷积层，而在这些敏感层；把位宽继续压低而不扩大高精度旁路，收益会被音质问题抵消。</p>\n<p>工程落点因此是一条分层配置规则：按层敏感度分析把网络切成三段——高精度段（输出投影、RVQ 码本）、完整 INT8 段（主体卷积与线性层，权重 per-channel、激活 per-channel 加平滑）、以及可选的更低比特段（仅限对失真不敏感且经实测验证的层）。每段的边界由实测的 $T_{\\text{epi}}$、$T_{\\text{mix}}$ 与音质指标共同划定，而不是由全局统一位宽决定。这条规则的可执行形式是：先在全 BF16 基线上测出各层的时间占比与带宽占比，再逐层替换为 INT8 并记录端到端变化，保留那些“替换后端到端确实变快且音质指标不退化”的层，其余回退——量化配置的最终形态是实测出来的层集合，而非一个全局开关。</p>\n\n<h3 id=\"alg-codec-int8-quant-sec-53\">五十三 · 与相邻算法的边界对照：何时选 INT8 PTQ，何时不选</h3>\n<p>本方案的定位必须放在同族算法的坐标系里看：它作用于卷积与线性层的<em>数值表示</em>，与声码器分块流式上采样（改变分块策略）、非自回归时长预测并行合成（改变步数结构）完全正交——后两者优化的是调度与迭代结构，INT8 PTQ 只压缩单次前向的权重带宽与矩阵乘成本。因此决策的第一条判据是：瓶颈在<strong>权重驻留显存与多路并发路数</strong>时选本方案；瓶颈在<strong>解码步数或上采样分块流水</strong>时，量化收益被结构开销淹没。第二条判据是敏感层比例：RVQ 码本查找与输出投影必须保留 FP16/BF16 分支，若这部分在总 FLOPs 中占比过高，混合精度分支的调度开销会吃掉 INT8 的吞吐增益。</p>\n<p>失效条件可以用误差上界直接读出：</p>\n<div class=\"formula\">$$\\text{err} \\le \\frac{\\Delta_W \\|X\\| + \\Delta_X \\|W\\|}{2}$$</div>\n<p>平滑变换 $\\hat{x}=x\\cdot s,\\ \\hat{W}=W/s$ 的作用是把 $\\Delta_X\\|W\\|$ 项转移到 $\\Delta_W\\|X\\|$ 项，使两项量级接近；但若校准集只覆盖单一说话人或单一语种，$\\max(|x_j|)$ 被低估，上线遇到高能量音频时 INT8 饱和削波，误差上界失效，表现为爆音与失真。这是本方案最典型的失败模式，也是它与“内容自适应校准”路线的分水岭。</p>\n<table class=\"mini\"><thead><tr><th>相邻方案</th><th>选它的条件</th><th>选 INT8 PTQ 的条件</th></tr></thead><tbody><tr><td>分块流式上采样</td><td>首包延迟受限、需边收边出</td><td>离线或整段合成、并发路数受限</td></tr><tr><td>非自回归并行合成</td><td>步数结构是主要开销</td><td>单次前向的权重带宽是主要开销</td></tr><tr><td>INT4 极低比特</td><td>显存极端受限且可接受重训练</td><td>RVQ 码本与输出层失真不可接受</td></tr></tbody></table>\n<p>系统代价上要按层实测而非全局套用：per-channel 激活量化在 epilogue 引入额外反量化与缩放开销，若某卷积层本身已受带宽限制，端到端吞吐不升反降。工程判断是——先量化权重 per-channel、激活保持 per-tensor，测出吞吐基线；仅对激活动态范围跨通道差异大的层升级为 per-channel，并用敏感度分析强制锁定 RVQ 码本与输出投影的高精度分支。规模上限由混合精度分支比例与校准集覆盖度共同决定，边缘场景应按目标内容分布重做校准，而非复用云端校准表。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2022 · 自回归与非自回归声学建模</td></tr><tr><td>解决什么</td><td>神经编解码器与声码器卷积层权重与激活占用显存大、带宽压力高，在边缘或多路并发服务中限制吞吐与并发路数。</td></tr><tr><td>一句话机制</td><td>对编解码器/声码器的卷积与线性层做训练后量化（PTQ），用 per-channel 权重缩放与激活平滑（SmoothQ…</td></tr><tr><td>代价与失效</td><td>RVQ 码本查找与输出层对量化敏感，需保留高精度分支，混合精度增加调度复杂度；激活动态范围随音频内容波动大，校准集偏差会导致爆音或失真</td></tr><tr><td>后继</td><td>残差矢量量化流式解码</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-codec-int8-quant · 共 8 个片段</p>\n";break;}}})();
